        self.spinNx.valueChanged.connect(self._enforce_rectangle_lock_from_resolution)
        sim_layout.addWidget(self.spinNx, 2, 1)

        sim_layout.addWidget(QLabel("Pixels Y (Ny):"), 3, 0)
