        noise_layout.addWidget(self.chkLineNoise, row, 0, 1, 3)
        row += 1

        self.spinLineNoiseSigmaNm = QDoubleSpinBox()
        self.spinLineNoiseSigmaNm.setRange(0.0, 5.0)
