    def _format_nma_flexible_fit_report(self, result):
        before = result.get("before", {}) or {}
        after = result.get("after", {}) or {}
        settings = result.get("settings", {}) or {}
        amplitudes = np.asarray(
            result.get("mode_amplitudes_nm", []), dtype=float
        )
        eigenvalues = np.asarray(
            result.get("mode_eigenvalues", []), dtype=float
        )
        fitted_mode_numbers = np.asarray(
            result.get("fitted_mode_numbers", []), dtype=int
        )
        before_rmsd = before.get("rmsd")
        after_rmsd = after.get("rmsd")
        improvement = None
        if before_rmsd is not None and after_rmsd is not None:
            improvement = float(before_rmsd) - float(after_rmsd)
        fitted_rms = float(result.get("fitted_rms_displacement_nm", 0.0))
        warning = ""
        if improvement is not None and improvement < max(
            0.02, 0.003 * len(amplitudes)
        ):
            warning = (
                "Warning: RMSD improvement is small relative to the fitted "
                "mode count; inspect for overfitting."
            )

        lines = [
            "AFM Simulator NMA Flexible Fit Report",
            f"Date: {datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}",
            f"Real AFM: {getattr(self, 'real_asd_path', '') or '(current frame)'}",
            f"Profile: {result.get('profile', '-')}",
            f"NMA engine: {result.get('nma_method', '-')}",
            f"Atom selection: {settings.get('atom_selection', '-')}",
            f"PDB-safe automatic settings: "
            f"{bool(settings.get('auto_estimate', False))}",
            f"Cutoff distance: {settings.get('cutoff_angstrom', '-')} Å",
            f"First fitted mode: {settings.get('first_mode', '-')}",
            f"Fitted modes: {len(amplitudes)}",
            f"Fitted DOF: {len(amplitudes)} (global pose fixed after Estimate Pose)",
            f"Max amplitude per mode: {settings.get('max_amplitude_nm', '-')} nm RMS",
            f"PDB geometry amplitude estimate: "
            f"{settings.get('pdb_estimated_max_amplitude_nm', '-')} nm RMS",
            f"Mode-specific safety clamp applied: "
            f"{bool(settings.get('mode_specific_safety_clamped', False))}",
            f"RMS structural displacement: {fitted_rms:.6g} nm",
            f"Configured RMS limit: {result.get('max_total_rms_nm', '-')} nm",
            f"Preview max resolution: {settings.get('preview_max_px', '-')} px",
            f"Penalty weights (energy/strain/clash): "
            f"{settings.get('mode_energy_weight', '-')} / "
            f"{settings.get('backbone_strain_weight', '-')} / "
            f"{settings.get('clash_weight', '-')}",
            f"Evaluations: {int(result.get('eval_count', 0))}",
            "",
            "Metrics",
            f"  RMSD before: {before_rmsd if before_rmsd is not None else '-'} nm",
            f"  RMSD after : {after_rmsd if after_rmsd is not None else '-'} nm",
            f"  ZNCC before: {before.get('zncc', '-')}",
            f"  ZNCC after : {after.get('zncc', '-')}",
        ]
        if improvement is not None:
            lines.append(f"  RMSD improvement: {improvement:.6g} nm")
        if warning:
            lines.extend(["", warning])
        lines.extend(["", "Normal Mode Amplitudes"])
        for position, amplitude in enumerate(amplitudes):
            mode_number = (
                int(fitted_mode_numbers[position])
                if position < fitted_mode_numbers.size
                else position + 1
            )
            eigenvalue = (
                float(eigenvalues[position])
                if position < eigenvalues.size else float("nan")
            )
            lines.append(
                f"  Mode {mode_number}: "
                f"amplitude={float(amplitude):.6g} nm RMS, "
                f"eigenvalue={eigenvalue:.6g}"
            )
        lines.extend([
            "",
            "Scientific note",
            "  Amplitudes multiply ANM eigenvectors normalized to 1 nm RMS "
            "C-alpha/P displacement.",
            "  Harmonic mode-energy, sequential-backbone strain, and total "
            "displacement penalties constrain the fit.",
            "  Candidates that introduce a new severe heavy-atom clash are "
            "rejected during optimization.",
            "  The fitted conformation is an AFM-supported model, not proof of "
            "a unique molecular state.",
        ])
        return "\n".join(lines) + "\n"

    def _write_current_structure_pdb(
        self,
        path,
        apply_display_rotation=True,
        coordinates=None,
    ):
        if getattr(self, "atoms_data", None) is None:
            raise ValueError("No atom data loaded")
        required = ("x", "y", "z", "element", "atom_name", "residue_name", "chain_id", "residue_id")
        if not all(name in self.atoms_data for name in required):
            raise ValueError("Atom data is incomplete")
        n_atoms = len(self.atoms_data["x"])
        local_coords = (
            self._current_atom_coords_array()
            if coordinates is None
            else np.asarray(coordinates, dtype=float)
        )
        if local_coords is None or local_coords.shape != (n_atoms, 3):
            raise ValueError("Explicit PDB coordinates do not match atom data")
        if apply_display_rotation:
            output_coords = self._apply_current_rotation_to_coords(local_coords)
            coordinate_error = "Failed to apply the current Estimate Pose rotation"
        else:
            output_coords = np.asarray(local_coords, dtype=float)
            coordinate_error = "Failed to obtain the current local coordinates"
        if output_coords is None or output_coords.shape != (n_atoms, 3):
            raise ValueError(coordinate_error)
        with open(path, "w", encoding="ascii") as f:
            for i in range(n_atoms):
                serial = (i % 99999) + 1
                element = str(self.atoms_data["element"][i]).strip()[:2] or "C"
                atom_name = self._format_pdb_atom_name(self.atoms_data["atom_name"][i], element)
                res_name = str(self.atoms_data["residue_name"][i]).strip().upper()[:3] or "UNK"
                chain = str(self.atoms_data["chain_id"][i]).strip()[:1] or " "
                try:
                    residue_id = int(self.atoms_data["residue_id"][i])
                except Exception:
                    residue_id = 1
                residue_id = max(-999, min(9999, residue_id))
                icode = ""
                if "icode" in self.atoms_data:
                    icode = str(self.atoms_data["icode"][i]).strip()[:1]
                b_factor = 20.0
                if "b_factor" in self.atoms_data:
                    try:
                        b_factor = float(self.atoms_data["b_factor"][i])
                    except Exception:
                        pass
                x = float(output_coords[i, 0]) * 10.0
                y = float(output_coords[i, 1]) * 10.0
                z = float(output_coords[i, 2]) * 10.0
                f.write(
                    f"ATOM  {serial:5d} {atom_name} {res_name:>3} {chain:1}"
                    f"{residue_id:4d}{icode:1}   "
                    f"{x:8.3f}{y:8.3f}{z:8.3f}"
                    f"  1.00{b_factor:6.2f}          {element:>2}\n"
                )
            f.write("END\n")

    def _create_structure_comparison_actors(
        self,
        coords,
        color,
        opacity,
    ):
        """Create C-alpha trace and point actors for a comparison overlay."""
        arr = np.asarray(coords, dtype=float)
        n_atoms = len(self.atoms_data["x"])
        if arr.shape != (n_atoms, 3):
            raise ValueError("Comparison coordinates do not match atom data.")

        atom_names = np.asarray(
            self.atoms_data.get("atom_name", [""] * n_atoms)
        ).astype(str)
        selected = np.where(np.char.strip(atom_names) == "CA")[0]
        if selected.size < 2:
            selected = np.arange(n_atoms, dtype=int)

        points = vtk.vtkPoints()
        for atom_index in selected:
            points.InsertNextPoint(*arr[int(atom_index)].tolist())

        polydata = vtk.vtkPolyData()
        polydata.SetPoints(points)
        lines = vtk.vtkCellArray()
        chains = np.asarray(
            self.atoms_data.get("chain_id", [""] * n_atoms)
        ).astype(str)
        residue_ids = np.asarray(
            self.atoms_data.get("residue_id", np.arange(n_atoms))
        )
        for local_index in range(selected.size - 1):
            left = int(selected[local_index])
            right = int(selected[local_index + 1])
            same_chain = str(chains[left]).strip() == str(chains[right]).strip()
            try:
                sequential = int(residue_ids[right]) - int(residue_ids[left]) == 1
            except (TypeError, ValueError):
                sequential = False
            if not same_chain or not sequential:
                continue
            line = vtk.vtkLine()
            line.GetPointIds().SetId(0, local_index)
            line.GetPointIds().SetId(1, local_index + 1)
            lines.InsertNextCell(line)
        polydata.SetLines(lines)

        tube = vtk.vtkTubeFilter()
        tube.SetInputData(polydata)
        tube.SetRadius(0.035)
        tube.SetNumberOfSides(10)
        tube.CappingOn()
        tube.Update()
        tube_mapper = vtk.vtkPolyDataMapper()
        tube_mapper.SetInputConnection(tube.GetOutputPort())
        tube_mapper.ScalarVisibilityOff()
        trace_actor = vtk.vtkActor()
        trace_actor.SetMapper(tube_mapper)
        trace_actor.GetProperty().SetColor(*color)
        trace_actor.GetProperty().SetOpacity(float(opacity))

        sphere = vtk.vtkSphereSource()
        sphere.SetRadius(0.075)
        sphere.SetPhiResolution(10)
        sphere.SetThetaResolution(10)
        glyph = vtk.vtkGlyph3D()
        glyph.SetInputData(polydata)
        glyph.SetSourceConnection(sphere.GetOutputPort())
        glyph.SetScaleModeToDataScalingOff()
        glyph.Update()
        point_mapper = vtk.vtkPolyDataMapper()
        point_mapper.SetInputConnection(glyph.GetOutputPort())
        point_mapper.ScalarVisibilityOff()
        point_actor = vtk.vtkActor()
        point_actor.SetMapper(point_mapper)
        point_actor.GetProperty().SetColor(*color)
        point_actor.GetProperty().SetOpacity(float(opacity))

        pipelines = [
            points,
            polydata,
            lines,
            tube,
            tube_mapper,
            sphere,
            glyph,
            point_mapper,
        ]
        return [trace_actor, point_actor], pipelines

    def show_flexible_fit_structure_comparison(self):
        """Overlay the loaded Original and accepted best-fit structures."""
        result = getattr(self, "flexible_fit_result", None) or {}
        expected_shape = (
            len(self.atoms_data["x"]),
            3,
        ) if getattr(self, "atoms_data", None) is not None else None
        if expected_shape is None:
            QMessageBox.information(
                self,
                "Compare Structures",
                "Run and accept a Flexible Fit before comparing structures.",
            )
            return
        try:
            original = select_flexible_fit_coordinates(
                result,
                "original",
                expected_shape[0],
            )
            fitted = select_flexible_fit_coordinates(
                result,
                "best_fit",
                expected_shape[0],
            )
        except FlexibleFitBackendError:
            QMessageBox.information(
                self,
                "Compare Structures",
                "Run and accept a Flexible Fit before comparing structures.",
            )
            return
        session_original = self._session_original_structure_coords(
            expected_atom_count=expected_shape[0]
        )
        if session_original is not None:
            original = session_original

        original_display = self._apply_current_rotation_to_coords(original)
        fitted_display = self._apply_current_rotation_to_coords(fitted)
        if original_display is None or fitted_display is None:
            QMessageBox.warning(
                self,
                "Compare Structures",
                "Failed to apply the current display orientation.",
            )
            return

        dialog = QDialog(self)
        dialog.setWindowTitle("Original (loaded) vs Best-fit Structure")
        dialog.setAttribute(Qt.WA_DeleteOnClose, True)
        dialog.resize(960, 720)
        outer = QVBoxLayout(dialog)

        displacement = fitted - original
        all_atom_rmsd = float(
            np.sqrt(np.mean(np.sum(displacement ** 2, axis=1)))
        )
        atom_names = np.asarray(
            self.atoms_data.get("atom_name", [""] * expected_shape[0])
        ).astype(str)
        ca_mask = np.char.strip(atom_names) == "CA"
        ca_rmsd = (
            float(np.sqrt(np.mean(np.sum(displacement[ca_mask] ** 2, axis=1))))
            if np.any(ca_mask)
            else all_atom_rmsd
        )
        method_names = {
            "rigid_domains": "Rigid Domains",
            "nma": "Linear ANM",
            "nmff": "Iterative NMFF-AFM",
            "nolb": "Nonlinear NMA (NOLB)",
            "afmfit": "Official AFMfit (external)",
        }
        method = method_names.get(
            str(result.get("fit_model", "")),
            str(result.get("fit_model", "Flexible Fit")),
        )
        summary = QLabel(
            f"Method: {method}    "
            f"All-atom RMS displacement: {all_atom_rmsd:.4f} nm    "
            f"Cα RMS displacement: {ca_rmsd:.4f} nm",
            dialog,
        )
        summary.setTextInteractionFlags(Qt.TextSelectableByMouse)
        outer.addWidget(summary)

        legend = QHBoxLayout()
        original_check = QCheckBox("Original (loaded)", dialog)
        original_check.setChecked(True)
        original_check.setStyleSheet(
            "QCheckBox { color: rgb(145, 145, 145); font-weight: bold; }"
        )
        fitted_check = QCheckBox("Best-fit structure", dialog)
        fitted_check.setChecked(True)
        fitted_check.setStyleSheet(
            "QCheckBox { color: rgb(20, 205, 235); font-weight: bold; }"
        )
        legend.addWidget(original_check)
        legend.addWidget(fitted_check)
        legend.addStretch(1)
        outer.addLayout(legend)

        vtk_widget = QVTKRenderWindowInteractor(dialog)
        render_window = vtk_widget.GetRenderWindow()
        if render_window is None:
            QMessageBox.warning(
                self,
                "Compare Structures",
                "VTK Qt rendering is not available in this environment.",
            )
            dialog.deleteLater()
            return
        renderer = vtk.vtkRenderer()
        renderer.SetBackground(0.06, 0.06, 0.09)
        render_window.AddRenderer(renderer)
        outer.addWidget(vtk_widget, 1)

        original_actors, original_pipeline = (
            self._create_structure_comparison_actors(
                original_display,
                (0.58, 0.58, 0.58),
                0.48,
            )
        )
        fitted_actors, fitted_pipeline = self._create_structure_comparison_actors(
            fitted_display,
            (0.08, 0.80, 0.92),
            0.92,
        )
        for actor in original_actors + fitted_actors:
            renderer.AddActor(actor)

        controls = QHBoxLayout()
        reset_button = QPushButton("Reset View", dialog)
        close_button = QPushButton("Close", dialog)
        controls.addStretch(1)
        controls.addWidget(reset_button)
        controls.addWidget(close_button)
        outer.addLayout(controls)

        def set_visibility(actors, visible):
            for actor in actors:
                actor.SetVisibility(bool(visible))
            render_window.Render()

        original_check.toggled.connect(
            lambda visible: set_visibility(original_actors, visible)
        )
        fitted_check.toggled.connect(
            lambda visible: set_visibility(fitted_actors, visible)
        )
        reset_button.clicked.connect(
            lambda: (renderer.ResetCamera(), render_window.Render())
        )
        close_button.clicked.connect(dialog.close)

        interactor = render_window.GetInteractor()
        if interactor is not None:
            interactor.SetInteractorStyle(vtk.vtkInteractorStyleTrackballCamera())
        renderer.ResetCamera()
        vtk_widget.Initialize()
        render_window.Render()

        dialog._vtk_widget = vtk_widget
        dialog._vtk_renderer = renderer
        dialog._vtk_actors = original_actors + fitted_actors
        dialog._vtk_pipelines = original_pipeline + fitted_pipeline
        self.structure_comparison_windows.append(dialog)

        def remove_window_reference():
            try:
                self.structure_comparison_windows.remove(dialog)
            except ValueError:
                pass

        dialog.destroyed.connect(remove_window_reference)
        dialog.show()

    def save_flexible_fit_outputs(self):
        if not getattr(self, "flexible_fit_result", None):
            QMessageBox.information(
                self, "Save Fit", "Run a Flexible Fit method first."
            )
            return
        default_id = self.get_active_dataset_id() if hasattr(self, "get_active_dataset_id") else "afm_fit"
        directory = self.last_import_dir if getattr(self, "last_import_dir", "") and os.path.isdir(self.last_import_dir) else ""
        default_path = os.path.join(directory, f"{default_id}_flexible_fit.pdb") if directory else f"{default_id}_flexible_fit.pdb"
        save_path, _ = QFileDialog.getSaveFileName(
            self,
            "Save Flexible Fit PDB",
            default_path,
            "PDB files (*.pdb);;All Files (*)",
            options=QFileDialog.DontUseNativeDialog,
        )
        if not save_path:
            return
        if not save_path.lower().endswith(".pdb"):
            save_path += ".pdb"
        report_path = str(Path(save_path).with_name(Path(save_path).stem + "_report.txt"))
        try:
            fitted_coordinates = select_flexible_fit_coordinates(
                self.flexible_fit_result,
                "best_fit",
                len(self.atoms_data["x"]),
            )
            self._write_current_structure_pdb(
                save_path,
                coordinates=fitted_coordinates,
            )
            with open(report_path, "w", encoding="utf-8") as f:
                f.write(self.flexible_fit_report_text or self._format_flexible_fit_report(self.flexible_fit_result))
            QMessageBox.information(
                self,
                "Save Fit",
                f"Saved fitted PDB:\n{save_path}\n\nSaved report:\n{report_path}",
            )
        except Exception as e:
            QMessageBox.critical(self, "Save Fit", f"Failed to save fit outputs:\n{e}")

    def _pose_fit_is_poor(
        self,
        rmsd_nm=None,
        zncc=None,
        foreground_score=None,
    ):
        """Return whether stored pose metrics justify a fresh global search."""
        try:
            if foreground_score is not None and float(foreground_score) < 0.30:
                return True
        except Exception:
            pass
        try:
            if zncc is not None and float(zncc) < 0.60:
                return True
        except Exception:
            pass
        try:
            real = np.asarray(self.real_afm_nm, dtype=float)
            valid = np.isfinite(real) & (real > -1e8)
            values = real[valid]
            if values.size >= 4 and rmsd_nm is not None:
                dynamic_range = float(
                    np.percentile(values, 99.0)
                    - np.percentile(values, 1.0)
                )
                return (
                    dynamic_range > 1e-9
                    and float(rmsd_nm) > 0.35 * dynamic_range
                )
        except Exception:
            pass
        return False

    @staticmethod
    def _select_distinct_support_planes(
        candidates,
        max_count,
        min_separation_deg=20.0,
    ):
        """Return high-ranking support normals after angular non-max suppression."""
        ranked = sorted(
            (candidate for candidate in candidates if isinstance(candidate, dict)),
            key=lambda candidate: (
                float(candidate.get(
                    "support_score_A2",
                    candidate.get(
                        "score_geo",
                        candidate.get("contact_area_A2", 0.0),
                    ),
                )),
                float(candidate.get("contact_area_A2", 0.0)),
                float(candidate.get("tie_score", 0.0)),
                float(candidate.get("S_contact", 0.0)),
                -float(candidate.get("height_norm", np.inf)),
            ),
            reverse=True,
        )
        selected = []
        cosine_limit = float(np.cos(np.deg2rad(min_separation_deg)))
        for candidate in ranked:
            try:
                normal = np.asarray(candidate["n"], dtype=float).reshape(3)
                normal /= max(float(np.linalg.norm(normal)), 1e-12)
            except Exception:
                continue
            if any(
                float(np.dot(normal, old["n"])) > cosine_limit
                for old in selected
            ):
                continue
            copied = dict(candidate)
            copied["n"] = normal
            selected.append(copied)
            if len(selected) >= max(1, int(max_count)):
                break
        return selected

    @staticmethod
    def _filter_physically_supported_faces(
        faces,
        maximum_height_ratio=1.35,
        minimum_height_slack_A=5.0,
    ):
        """Exclude ranked faces that leave the rigid model markedly lifted."""
        valid_faces = []
        for face in faces:
            if not isinstance(face, dict):
                continue
            try:
                height_A = float(face["height_A"])
            except Exception:
                continue
            if not np.isfinite(height_A) or height_A <= 0.0:
                continue
            copied = dict(face)
            copied["height_A"] = height_A
            valid_faces.append(copied)
        if not valid_faces:
            return []

        minimum_height_A = min(face["height_A"] for face in valid_faces)
        maximum_height_A = max(
            minimum_height_A * float(maximum_height_ratio),
            minimum_height_A + float(minimum_height_slack_A),
        )
        physically_supported = [
            face
            for face in valid_faces
            if face["height_A"] <= maximum_height_A + 1e-9
        ]
        if physically_supported:
            return physically_supported
        return [
            min(valid_faces, key=lambda face: face["height_A"])
        ]

    def _rotation_matrix_align_support_normal(self, normal):
        """Return a rotation that maps one substrate normal onto lab -Z."""
        normal = np.asarray(normal, dtype=float).reshape(3)
        normal /= max(float(np.linalg.norm(normal)), 1e-12)
        target = np.array([0.0, 0.0, -1.0], dtype=float)
        cross = np.cross(normal, target)
        cosine = float(np.clip(np.dot(normal, target), -1.0, 1.0))
        sine = float(np.linalg.norm(cross))
        if sine < 1e-8:
            if cosine > 0.0:
                return np.eye(3, dtype=float)
            axis = self._make_perp_unit(normal)
            axis /= max(float(np.linalg.norm(axis)), 1e-12)
            x, y, z = axis
            return np.array([
                [-1.0 + 2.0 * x * x, 2.0 * x * y, 2.0 * x * z],
                [2.0 * x * y, -1.0 + 2.0 * y * y, 2.0 * y * z],
                [2.0 * x * z, 2.0 * y * z, -1.0 + 2.0 * z * z],
            ], dtype=float)
        vx = np.array([
            [0.0, -cross[2], cross[1]],
            [cross[2], 0.0, -cross[0]],
            [-cross[1], cross[0], 0.0],
        ], dtype=float)
        return np.eye(3) + vx + (vx @ vx) * (
            (1.0 - cosine) / (sine * sine)
        )

    @staticmethod
    def _vtk_xyz_euler_from_matrix(rotation_matrix):
        """Convert a 3x3 matrix to the RotateX/Y/Z convention used by VTK."""
        from scipy.spatial.transform import Rotation as ScipyRotation

        matrix = np.asarray(rotation_matrix, dtype=float).reshape(3, 3)
        with np.errstate(all="ignore"):
            euler = ScipyRotation.from_matrix(matrix).as_euler(
                "xyz",
                degrees=True,
            )
        return tuple(
            float((value + 180.0) % 360.0 - 180.0)
            for value in euler
        )

    def _ensure_substrate_support_planes_for_estimate_pose(self):
        """Run Find Initial Plane when Estimate Pose has no contact ranking yet.

        Contact-area ranking is a strong prior for Estimate Pose. If the user
        has not run Find Initial Plane, do it once here so ranked faces and the
        substrate-contact objective are available before pose search starts.
        """
        if self._prepare_estimate_pose_support_context() is not None:
            return True
        if getattr(self, "atoms_data", None) is None:
            return False

        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            QApplication.processEvents()
            self.handle_find_initial_plane()
            QApplication.processEvents()
        finally:
            QApplication.restoreOverrideCursor()
        return self._prepare_estimate_pose_support_context() is not None

    def _prepare_estimate_pose_support_context(self):
        """Build substrate-contact data shared by all Estimate Pose candidates."""
        if not bool(getattr(self, "pose_support_constraint_active", False)):
            return None
        initial = getattr(self, "last_initial_plane_result", None)
        if not isinstance(initial, dict):
            return None
        support_faces = initial.get("support_pose_candidates", None)
        if not isinstance(support_faces, list) or not support_faces:
            return None

        atoms = getattr(self, "atoms_data", None)
        if not isinstance(atoms, dict):
            return None
        try:
            coords_nm = np.column_stack([
                atoms["x"],
                atoms["y"],
                atoms["z"],
            ]).astype(float)
        except Exception:
            return None
        if coords_nm.ndim != 2 or coords_nm.shape[0] == 0:
            return None

        surface_indices = np.asarray(
            initial.get("surface_indices", []),
            dtype=int,
        ).reshape(-1)
        surface_indices = surface_indices[
            (surface_indices >= 0) & (surface_indices < coords_nm.shape[0])
        ]
        if surface_indices.size == 0:
            return None

        elements = atoms.get("element", None)
        if elements is None or len(elements) != coords_nm.shape[0]:
            elements = np.array(["C"] * coords_nm.shape[0])
        radii_all_A = np.array(
            [self._vdw_radius_angstrom(element) for element in elements],
            dtype=float,
        )

        prepared_faces = []
        for index, face in enumerate(support_faces):
            if not isinstance(face, dict):
                continue
            try:
                rotation_matrix = np.asarray(
                    face["rotation_matrix"],
                    dtype=float,
                ).reshape(3, 3)
                contact_area_A2 = float(face["contact_area_A2"])
                reference_height_A = float(face["height_A"])
            except Exception:
                continue
            if (
                not np.all(np.isfinite(rotation_matrix))
                or not np.isfinite(contact_area_A2)
                or contact_area_A2 <= 1e-9
            ):
                continue
            prepared_faces.append({
                "rank": int(face.get("rank", index + 1)),
                "normal": np.asarray(face.get("normal"), dtype=float),
                "rotation_matrix": rotation_matrix,
                "contact_area_A2": contact_area_A2,
                "height_A": max(reference_height_A, 1e-6),
                "support_score_A2": float(
                    face.get("support_score_A2", contact_area_A2)
                ),
            })
        if not prepared_faces:
            return None
        ranked_face_count = len(prepared_faces)
        prepared_faces = self._filter_physically_supported_faces(
            prepared_faces,
            maximum_height_ratio=1.35,
            minimum_height_slack_A=5.0,
        )
        if not prepared_faces:
            return None

        base_matrix = np.eye(3, dtype=float)
        try:
            vtk_matrix = self.base_transform.GetMatrix()
            base_matrix = np.array([
                [
                    float(vtk_matrix.GetElement(row, column))
                    for column in range(3)
                ]
                for row in range(3)
            ], dtype=float)
        except Exception:
            pass

        return {
            "faces": prepared_faces,
            "ranked_face_count": ranked_face_count,
            "physically_supported_face_count": len(prepared_faces),
            "surface_indices": surface_indices,
            "radii_A": radii_all_A[surface_indices],
            "delta_contact_A": max(
                float(initial.get("delta_contact_A", 1.5)),
                1e-6,
            ),
            "projection_grid_A": max(
                float(initial.get("projection_grid_A", 0.75)),
                0.1,
            ),
            "maximum_contact_area_A2": max(
                face["contact_area_A2"] for face in prepared_faces
            ),
            "maximum_support_score_A2": max(
                face["support_score_A2"] for face in prepared_faces
            ),
            "base_rotation_matrix": base_matrix,
            "active_face_rank": int(
                getattr(
                    self,
                    "pose_support_active_face_rank",
                    initial.get("applied_face_rank", 1),
                )
            ),
        }

    def _estimate_pose_support_metrics(
        self,
        rotated_coords_nm,
        support_context,
        support_face,
    ):
        """Measure contact retained relative to one ranked support face."""
        if not isinstance(support_context, dict) or not isinstance(support_face, dict):
            return None
        coords_nm = np.asarray(rotated_coords_nm, dtype=float)
        indices = np.asarray(
            support_context.get("surface_indices", []),
            dtype=int,
        ).reshape(-1)
        radii_A = np.asarray(
            support_context.get("radii_A", []),
            dtype=float,
        ).reshape(-1)
        if (
            coords_nm.ndim != 2
            or coords_nm.shape[1] != 3
            or indices.size == 0
            or radii_A.size != indices.size
            or np.any(indices < 0)
            or np.any(indices >= coords_nm.shape[0])
        ):
            return None

        result = self._eval_geo(
            coords_nm[indices] * 10.0,
            radii_A,
            np.array([0.0, 0.0, -1.0], dtype=float),
            float(support_context["delta_contact_A"]),
            0.0,
            float(support_context["projection_grid_A"]),
        )
        if not isinstance(result, dict):
            return None
        contact_area_A2 = max(
            0.0,
            float(result.get("contact_area_A2", 0.0)),
        )
        reference_area_A2 = max(
            float(support_face.get("contact_area_A2", 0.0)),
            1e-9,
        )
        face_support_score_A2 = max(
            float(support_face.get(
                "support_score_A2",
                reference_area_A2,
            )),
            1e-9,
        )
        maximum_support_score_A2 = max(
            float(support_context.get(
                "maximum_support_score_A2",
                face_support_score_A2,
            )),
            1e-9,
        )
        height_A = max(float(result.get("height_A", 0.0)), 0.0)
        reference_height_A = max(
            float(support_face.get("height_A", height_A)),
            1e-6,
        )
        return {
            "contact_area_A2": contact_area_A2,
            "support_ratio": contact_area_A2 / reference_area_A2,
            "face_quality_ratio": (
                face_support_score_A2 / maximum_support_score_A2
            ),
            "height_A": height_A,
            "height_ratio": height_A / reference_height_A,
            "contact_atoms": int(result.get("Nc", 0) or 0),
        }

    @staticmethod
    def _substrate_constrained_pose_score(
        image_score,
        support_ratio,
        face_quality_ratio,
        height_ratio=1.0,
        *,
        minimum_support_ratio=0.80,
        maximum_height_ratio=1.15,
    ):
        """Combine image agreement with a strong within-face contact prior.

        Contact retention is treated as a hard-ish constraint: large contact
        loss or height growth is rejected, and milder losses still outweigh
        typical image-score gains so the molecule stays flat on the substrate.
        """
        try:
            image_score = float(image_score)
            support_ratio = float(support_ratio)
            face_quality_ratio = float(face_quality_ratio)
            height_ratio = float(height_ratio)
        except Exception:
            return -1e9
        if (
            not np.isfinite(image_score)
            or not np.isfinite(support_ratio)
            or not np.isfinite(face_quality_ratio)
            or not np.isfinite(height_ratio)
            or support_ratio < float(minimum_support_ratio)
            or height_ratio > float(maximum_height_ratio)
        ):
            return -1e9
        retained_contact_penalty = 1.50 * max(0.0, 0.95 - support_ratio)
        face_rank_penalty = 0.10 * max(0.0, 1.0 - face_quality_ratio)
        lift_penalty = 1.00 * max(0.0, height_ratio - 1.0)
        return (
            image_score
            - retained_contact_penalty
            - face_rank_penalty
            - lift_penalty
        )

    def _select_estimate_pose_precision(self):
        """Compact precision dialog for Estimate Pose.

        Returns (selected_level, refine_current, search_mode, refine_kind) or
        None when canceled. refine_kind is one of:
          - "preserve_plane": after Find Initial Plane / current rotation only
          - "local_pose": after a successful Estimate Pose
          - "global": full coarse seeding
        """
        prior_pose = getattr(self, "pose", None)
        from_initial_plane = bool(
            getattr(self, "pose_seed_from_initial_plane", False)
        )
        has_ranked_support_planes = bool(
            getattr(self, "pose_support_constraint_active", False)
            and isinstance(
                getattr(self, "last_initial_plane_result", None),
                dict,
            )
            and getattr(
                self,
                "last_initial_plane_result",
                {},
            ).get("support_pose_candidates")
        )
        has_prior_pose = (
            (not from_initial_plane)
            and isinstance(prior_pose, dict)
            and prior_pose.get("score") is not None
            and all(
                key in prior_pose
                for key in ("rot_x_deg", "rot_y_deg", "rot_z_deg")
            )
        )
        prior_pose_is_poor = False
        if has_prior_pose:
            prior_pose_is_poor = self._pose_fit_is_poor(
                rmsd_nm=prior_pose.get("rmsd_nm"),
                zncc=prior_pose.get("zncc"),
                foreground_score=prior_pose.get("foreground_score"),
            )
        if has_prior_pose:
            refine_label = "Refine current pose"
            refine_kind_default = "local_pose"
            refine_hint = (
                "Fine-tune only in-plane Z rotation and tip XY around the "
                "current pose. X/Y tilt stays fixed."
            )
        elif from_initial_plane:
            refine_label = "Refine current rotation"
            refine_kind_default = "preserve_plane"
            refine_hint = (
                "Compare the ranked Find Initial Plane contact faces, then "
                "refine mainly the in-plane angle of the best match."
            )
        else:
            refine_label = "Refine current rotation"
            refine_kind_default = "preserve_plane"
            refine_hint = (
                "Start from the current Rotation XYZ. X/Y stay near the "
                "current tilt; Z is searched more freely."
            )

        precision_levels = [
            f"Medium ({refine_label})",
            f"High ({refine_label})",
            "Low (Global search)",
            "Medium (Global search)",
            "High (Global search)",
        ]

        dialog = QDialog(self)
        dialog.setWindowTitle("Estimate Pose")
        dialog.setFixedWidth(420)
        outer = QVBoxLayout(dialog)
        outer.setContentsMargins(12, 12, 12, 12)
        outer.setSpacing(8)

        title = QLabel("Precision")
        title.setStyleSheet("font-weight: bold;")
        outer.addWidget(title)

        hint = QLabel(
            f"{refine_label}: {refine_hint}\n"
            + (
                "Global search: compare the top-ranked substrate-contact "
                "faces, including an opposite face when it ranks highly.\n"
                if has_ranked_support_planes
                else "Global search: explore many seed orientations.\n"
            )
            + (
                "Recommended: Medium Global search is preselected because "
                "there is no reliable previous pose."
                if (
                    (not has_prior_pose and not from_initial_plane)
                    or prior_pose_is_poor
                )
                else "Recommended: refine the current pose/orientation."
            )
        )
        hint.setWordWrap(True)
        hint.setStyleSheet("color: #444;")
        outer.addWidget(hint)

        combo = QComboBox(dialog)
        combo.addItems(precision_levels)
        use_global_default = (
            (not has_prior_pose and not from_initial_plane)
            or prior_pose_is_poor
        )
        combo.setCurrentIndex(3 if use_global_default else 0)
        outer.addWidget(combo)

        buttons = QDialogButtonBox(
            QDialogButtonBox.Ok | QDialogButtonBox.Cancel,
            parent=dialog,
        )
        buttons.accepted.connect(dialog.accept)
        buttons.rejected.connect(dialog.reject)
        outer.addWidget(buttons)

        if dialog.exec_() != QDialog.Accepted:
            return None

        selected_choice = str(combo.currentText())
        selected_level = selected_choice.split(" ", 1)[0]
        refine_current = "(Refine current" in selected_choice
        if refine_current:
            search_mode = refine_label
            refine_kind = refine_kind_default
        else:
            search_mode = "Global search"
            refine_kind = "global"
        return selected_level, refine_current, search_mode, refine_kind

    def estimate_pose_from_real(self):
        """Estimate Rotation XYZ by iteratively re-simulating AFM and maximizing similarity."""
        if self.real_afm_nm is None:
            QMessageBox.information(self, "Pose", "Real AFM is not loaded.")
            return
        if self.atoms_data is None:
            QMessageBox.warning(self, "Pose", "PDB is not loaded.")
            return

        # Keep explicit simulation from conflicting with active workers.
        if self.is_worker_running(getattr(self, 'sim_worker', None), attr_name='sim_worker') or \
           self.is_worker_running(getattr(self, 'sim_worker_high_res', None), attr_name='sim_worker_high_res'):
            QMessageBox.information(self, "Pose", "Another simulation is running. Please wait.")
            return
        if self.is_worker_running(getattr(self, 'sim_worker_silent', None), attr_name='sim_worker_silent'):
            self.stop_worker(self.sim_worker_silent, timeout_ms=300, allow_terminate=True, worker_name="sim_worker_silent")
            if self.is_worker_running(getattr(self, 'sim_worker_silent', None), attr_name='sim_worker_silent'):
                QMessageBox.information(self, "Pose", "Another simulation is running. Please wait.")
                return

        # Contact-area ranking is required for a strong substrate prior.
        # Run Find Initial Plane automatically when it has not been done yet.
        # Tip Z is display-only; keep it fixed across Find Initial Plane and
        # the whole Estimate Pose search (XY tip / Rotation may still change).
        orig_tz = self._get_tip_z_nm()
        if self._prepare_estimate_pose_support_context() is None:
            if not self._ensure_substrate_support_planes_for_estimate_pose():
                self._set_tip_z_nm(orig_tz, update=True)
                QMessageBox.warning(
                    self,
                    "Pose",
                    "Find Initial Plane could not build substrate-contact "
                    "faces.\nEstimate Pose needs contact-area ranking first.",
                )
                return
        self._set_tip_z_nm(orig_tz, update=False)

        try:
            orig_rx = float(self.rotation_widgets['X']['spin'].value())
            orig_ry = float(self.rotation_widgets['Y']['spin'].value())
            orig_rz = float(self.rotation_widgets['Z']['spin'].value())
        except Exception:
            QMessageBox.warning(self, "Pose", "Rotation controls are unavailable.")
            return
        orig_tx, orig_ty = self._get_tip_center_xy_nm()

        allowed_axes = self._get_pose_rotation_axes()
        refine_axes = [axis for axis in ('X', 'Y', 'Z') if allowed_axes.get(axis, True)]
        if not refine_axes:
            QMessageBox.warning(self, "Pose", "Select at least one rotation axis for Estimate Pose.")
            return
        axes_text = ", ".join(refine_axes)

        real_p = self.preprocess_pose_image(self.real_afm_nm)
        if real_p is None:
            QMessageBox.warning(self, "Pose", "Real AFM image is invalid for pose estimation.")
            return
        meta = self._get_real_afm_simulation_meta()
        if meta is None:
            QMessageBox.warning(self, "Pose", "Real AFM metadata is incomplete.")
            return
        scan_x_nm, scan_y_nm, nx, ny = meta
        pixel_x_nm = float(scan_x_nm) / max(float(nx), 1.0)
        pixel_y_nm = float(scan_y_nm) / max(float(ny), 1.0)
        self._ensure_tip_xy_range_for_scan(scan_x_nm, scan_y_nm)
        self._set_tip_z_nm(orig_tz, update=False)

        selected = self._select_estimate_pose_precision()
        if selected is None:
            return
        selected_level, refine_current, search_mode, refine_kind = selected

        profiles = {
            "Low": {
                "seed_offsets": [(0.0, 0.0), (30.0, 0.0), (0.0, 30.0)],
                "z_step": 45.0,
                "refine_start_count": 2,
                "refine_steps": (20.0, 10.0, 5.0, 2.0),
                "xy_refine_steps_px": (8.0, 4.0, 2.0, 1.0),
                "max_refine_iter": 8,
                "preserve_plane_z_step": 30.0,
                "max_tilt_dev_deg": 12.0,
                "max_pose_dev_deg": 15.0,
                "max_local_rotation_dev_deg": 4.0,
                "max_local_shift_px": 2.0,
                "support_face_count": 3,
                "preserve_tilt_steps": (6.0, 3.0, 1.5, 0.75),
                "final_z_steps_deg": (4.0, 2.0, 1.0),
                "max_final_z_change_deg": 10.0,
            },
            "Medium": {
                "seed_offsets": [
                    (0.0, 0.0),
                    (45.0, 0.0), (-45.0, 0.0), (90.0, 0.0),
                    (0.0, 45.0), (0.0, -45.0), (0.0, 90.0),
                    (45.0, 45.0), (-45.0, 45.0),
                    (45.0, -45.0), (-45.0, -45.0),
                ],
                "z_step": 30.0,
                "refine_start_count": 4,
                "refine_steps": (15.0, 8.0, 4.0, 2.0, 1.0),
                "xy_refine_steps_px": (12.0, 6.0, 3.0, 1.5, 1.0),
                "max_refine_iter": 16,
                "preserve_plane_z_step": 20.0,
                "max_tilt_dev_deg": 18.0,
                "max_pose_dev_deg": 25.0,
                "max_local_rotation_dev_deg": 6.0,
                "max_local_shift_px": 3.0,
                "support_face_count": 5,
                "preserve_tilt_steps": (8.0, 4.0, 2.0, 1.0, 0.5),
                "final_z_steps_deg": (6.0, 3.0, 1.5, 0.5),
                "max_final_z_change_deg": 15.0,
            },
            "High": {
                "seed_offsets": [
                    (0.0, 0.0),
                    (30.0, 0.0), (-30.0, 0.0), (60.0, 0.0), (-60.0, 0.0),
                    (90.0, 0.0), (-90.0, 0.0), (135.0, 0.0),
                    (0.0, 30.0), (0.0, -30.0), (0.0, 60.0), (0.0, -60.0),
                    (0.0, 90.0), (0.0, -90.0),
                    (45.0, 45.0), (-45.0, 45.0),
                    (45.0, -45.0), (-45.0, -45.0),
                    (90.0, 45.0), (-90.0, 45.0),
                    (90.0, -45.0), (-90.0, -45.0),
                ],
                "z_step": 20.0,
                "refine_start_count": 8,
                "refine_steps": (12.0, 6.0, 3.0, 1.5, 0.75, 0.4),
                "xy_refine_steps_px": (16.0, 8.0, 4.0, 2.0, 1.0, 1.0),
                "max_refine_iter": 20,
                "preserve_plane_z_step": 15.0,
                "max_tilt_dev_deg": 25.0,
                "max_pose_dev_deg": 35.0,
                "max_local_rotation_dev_deg": 8.0,
                "max_local_shift_px": 4.0,
                "support_face_count": 8,
                "preserve_tilt_steps": (6.0, 3.0, 1.5, 0.75, 0.4),
                "final_z_steps_deg": (8.0, 4.0, 2.0, 1.0, 0.4),
                "max_final_z_change_deg": 20.0,
            },
        }
        cfg = profiles.get(str(selected_level), profiles["Medium"])
        if refine_current and refine_kind == "local_pose":
            # Keep the current substrate tilt; only nudge in-plane Z and tip XY.
            cfg = dict(cfg)
            cfg["refine_steps"] = (3.0, 1.5, 0.75, 0.4)
            cfg["xy_refine_steps_px"] = (2.0, 1.0, 0.5, 0.25)
            cfg["max_refine_iter"] = 10
            cfg["max_local_rotation_dev_deg"] = 8.0
            cfg["max_local_shift_px"] = 2.0
            cfg["final_z_steps_deg"] = (2.0, 1.0, 0.5)
            cfg["max_final_z_change_deg"] = 8.0
        support_context = self._prepare_estimate_pose_support_context()
        substrate_constrained = support_context is not None
        compare_ranked_faces = bool(
            substrate_constrained
            and (
                refine_kind != "local_pose"
                or not refine_current
            )
        )
        if substrate_constrained:
            if compare_ranked_faces:
                search_mode = (
                    f"{search_mode} "
                    f"({support_context['physically_supported_face_count']}/"
                    f"{support_context['ranked_face_count']} physically "
                    "supported faces)"
                )
            else:
                search_mode = (
                    f"{search_mode} (local active substrate face)"
                )
        if refine_current and refine_kind == "local_pose":
            search_mode = (
                f"{search_mode}; Z±"
                f"{cfg['max_local_rotation_dev_deg']:.0f} deg / "
                f"tip±{cfg['max_local_shift_px']:.0f} px "
                "(X/Y tilt fixed)"
            )
        # local_pose must not inherit the preserve-plane full-circle Z coarse
        # search just because a substrate face is active.
        preserve_plane = (
            refine_kind == "preserve_plane"
            or (
                substrate_constrained
                and not (refine_current and refine_kind == "local_pose")
            )
        )
        max_tilt_dev = float(
            cfg["max_tilt_dev_deg"] if preserve_plane else cfg["max_pose_dev_deg"]
        )
        max_z_dev = None if preserve_plane else float(cfg["max_pose_dev_deg"])
        active_refine_steps = (
            tuple(cfg["preserve_tilt_steps"])
            if preserve_plane
            else tuple(cfg["refine_steps"])
        )
        if refine_current and refine_kind == "local_pose":
            active_refine_steps = tuple(cfg["refine_steps"])

        eval_cache = {}
        support_cache = {}
        eval_count = 0
        best = {
            'rx': orig_rx, 'ry': orig_ry, 'rz': orig_rz,
            'tx': orig_tx, 'ty': orig_ty,
            'score': -1e9, 'dx': 0.0, 'dy': 0.0, 'rmsd': None, 'zncc': None,
            'foreground_zncc': None, 'foreground_dice': None,
            'image_score': -1e9, 'support_ratio': None,
            'face_quality_ratio': None, 'support_face_rank': None,
            'support_contact_area_A2': None, 'support_height_ratio': None,
        }
        cancel_requested = False
        if allowed_axes.get('Z', True):
            z_coarse = np.arange(-180.0, 180.0 + 1e-9, float(cfg["z_step"]))
        else:
            z_coarse = np.array([orig_rz], dtype=float)
        if preserve_plane and allowed_axes.get('Z', True):
            preserve_z_coarse = np.arange(
                -180.0,
                180.0 + 1e-9,
                float(cfg["preserve_plane_z_step"]),
            )
        else:
            preserve_z_coarse = np.array([orig_rz], dtype=float)
        support_faces = []
        active_support_face = None
        if substrate_constrained:
            all_support_faces = list(support_context["faces"])
            active_rank = int(support_context["active_face_rank"])
            active_support_face = next(
                (
                    face for face in all_support_faces
                    if int(face["rank"]) == active_rank
                ),
                all_support_faces[0],
            )
            if compare_ranked_faces:
                support_faces = all_support_faces[
                    :max(1, int(cfg["support_face_count"]))
                ]
                if all(
                    int(face["rank"]) != int(active_support_face["rank"])
                    for face in support_faces
                ):
                    support_faces.append(active_support_face)
            else:
                support_faces = [active_support_face]

        from scipy.spatial.transform import Rotation as ScipyRotation

        pose_base_rotation_matrix = np.eye(3, dtype=float)
        if substrate_constrained:
            pose_base_rotation_matrix = np.asarray(
                support_context["base_rotation_matrix"],
                dtype=float,
            )
        else:
            try:
                base_vtk_matrix = self.base_transform.GetMatrix()
                pose_base_rotation_matrix = np.array([
                    [
                        float(base_vtk_matrix.GetElement(row, column))
                        for column in range(3)
                    ]
                    for row in range(3)
                ], dtype=float)
            except Exception:
                pass
        original_local_rotation_matrix = ScipyRotation.from_euler(
            "xyz",
            [orig_rx, orig_ry, orig_rz],
            degrees=True,
        ).as_matrix()
        original_absolute_rotation_matrix = (
            original_local_rotation_matrix @ pose_base_rotation_matrix
        )

        def support_face_seed_euler(face, inplane_deg):
            angle = np.deg2rad(float(inplane_deg))
            cosine = float(np.cos(angle))
            sine = float(np.sin(angle))
            lab_z_rotation = np.array([
                [cosine, -sine, 0.0],
                [sine, cosine, 0.0],
                [0.0, 0.0, 1.0],
            ], dtype=float)
            absolute_rotation = (
                lab_z_rotation
                @ np.asarray(face["rotation_matrix"], dtype=float)
            )
            # update_actor_transform composes local * base. Convert each
            # absolute support orientation into the corresponding local matrix.
            local_rotation = (
                absolute_rotation
                @ pose_base_rotation_matrix.T
            )
            return self._vtk_xyz_euler_from_matrix(local_rotation)

        def substrate_lab_axis_candidate(center, axis, delta_deg):
            """Rotate a support pose about a lab/substrate axis, not an Euler slot."""
            current_local = ScipyRotation.from_euler(
                "xyz",
                [
                    float(center["rx"]),
                    float(center["ry"]),
                    float(center["rz"]),
                ],
                degrees=True,
            ).as_matrix()
            base_rotation = pose_base_rotation_matrix
            current_absolute = current_local @ base_rotation
            axis_key = str(axis).upper()
            axis_vector = {
                "X": [1.0, 0.0, 0.0],
                "Y": [0.0, 1.0, 0.0],
                "Z": [0.0, 0.0, 1.0],
            }[axis_key]
            lab_delta = ScipyRotation.from_rotvec(
                np.asarray(axis_vector, dtype=float)
                * np.deg2rad(float(delta_deg))
            ).as_matrix()
            candidate_absolute = lab_delta @ current_absolute
            candidate_local = candidate_absolute @ base_rotation.T
            return self._vtk_xyz_euler_from_matrix(candidate_local)

        ranked_face_coarse_count = (
            len(support_faces) * len(preserve_z_coarse) * 2
            if compare_ranked_faces
            else 0
        )
        coarse_eval_est = (
            2 + (
                ranked_face_coarse_count
                if compare_ranked_faces
                else (len(preserve_z_coarse) * 2 if preserve_plane else 0)
            )
            if refine_current
            else (
                ranked_face_coarse_count + 2
                if compare_ranked_faces
                else len(cfg["seed_offsets"]) * len(z_coarse) * 2 + 2
            )
        )
        max_eval_est = max(
            1,
            coarse_eval_est
            + int(cfg.get("refine_start_count", 4))
              * len(active_refine_steps)
              * int(cfg["max_refine_iter"])
              * (2 * len(refine_axes) + 4)
            + 2,
        )
        progress = QProgressDialog("Estimating pose...", "Cancel", 0, int(max_eval_est), self)
        progress.setWindowTitle("Estimate Pose")
        progress.setWindowModality(Qt.ApplicationModal)
        progress.setMinimumDuration(0)
        progress.setValue(0)
        progress.show()

        self._pose_estimation_running = True
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            def maybe_update_best(candidate):
                nonlocal best
                if candidate is not None and candidate.get('score', -1e9) > best['score']:
                    best = dict(candidate)
                    return True
                return False

            def residual_center_candidate(candidate):
                if candidate is None:
                    return None
                try:
                    dx = float(candidate.get('dx', 0.0))
                    dy = float(candidate.get('dy', 0.0))
                    tx = float(candidate.get('tx', orig_tx))
                    ty = float(candidate.get('ty', orig_ty))
                except Exception:
                    return None
                if abs(dx) < 0.25 and abs(dy) < 0.25:
                    return None
                # Positive image residual means the simulated image needs to move
                # right/down; decreasing the scan center produces that explicit shift.
                next_tx = tx - dx * pixel_x_nm
                next_ty = ty - dy * pixel_y_nm
                if refine_current and refine_kind == "local_pose":
                    max_shift_px = float(cfg["max_local_shift_px"])
                    next_tx = float(np.clip(
                        next_tx,
                        orig_tx - max_shift_px * pixel_x_nm,
                        orig_tx + max_shift_px * pixel_x_nm,
                    ))
                    next_ty = float(np.clip(
                        next_ty,
                        orig_ty - max_shift_px * pixel_y_nm,
                        orig_ty + max_shift_px * pixel_y_nm,
                    ))
                return evaluate(
                    candidate['rx'],
                    candidate['ry'],
                    candidate['rz'],
                    next_tx,
                    next_ty,
                    support_face=candidate.get("_support_face"),
                )

            def evaluate(
                rx,
                ry,
                rz,
                tx_nm=None,
                ty_nm=None,
                *,
                find_translation=False,
                support_face=None,
            ):
                nonlocal eval_count, cancel_requested
                if cancel_requested:
                    return None

                nrx = self.normalize_angle(rx)
                nry = self.normalize_angle(ry)
                nrz = self.normalize_angle(rz)
                if substrate_constrained and support_face is None:
                    support_face = active_support_face
                ok = self.set_rotation_controls_xyz(
                    nrx, nry, nrz,
                    apply_transform=True,
                    trigger_simulation=False,
                )
                rotated_coords = self.get_rotated_atom_coords()
                if tx_nm is None or ty_nm is None:
                    model_center = self._model_xy_centroid_nm(
                        rotated_coords
                    )
                    if model_center is None:
                        tx_nm, ty_nm = orig_tx, orig_ty
                    else:
                        tx_nm, ty_nm = model_center
                ntx, nty = self._clamp_tip_center_xy_nm(tx_nm, ty_nm)
                ntx, nty = self._set_tip_center_xy_nm(ntx, nty, update=False)
                support_face_rank = (
                    int(support_face["rank"])
                    if isinstance(support_face, dict)
                    else None
                )
                key = (
                    round(nrx, 3),
                    round(nry, 3),
                    round(nrz, 3),
                    round(ntx, 3),
                    round(nty, 3),
                    support_face_rank,
                )
                if key in eval_cache:
                    return eval_cache[key]

                if not ok:
                    result = {
                        'rx': nrx, 'ry': nry, 'rz': nrz, 'tx': ntx, 'ty': nty,
                        'score': -1e9, 'dx': 0.0, 'dy': 0.0, 'rmsd': None, 'zncc': None,
                        'foreground_zncc': None, 'foreground_dice': None,
                        'image_score': -1e9, 'support_ratio': None,
                        'face_quality_ratio': None,
                        'support_face_rank': support_face_rank,
                        '_support_face': support_face,
                    }
                    eval_cache[key] = result
                    return result

                support_metrics = None
                if substrate_constrained:
                    support_key = (
                        round(nrx, 3),
                        round(nry, 3),
                        round(nrz, 3),
                        support_face_rank,
                    )
                    support_metrics = support_cache.get(support_key)
                    if support_metrics is None:
                        support_metrics = self._estimate_pose_support_metrics(
                            rotated_coords,
                            support_context,
                            support_face,
                        )
                        support_cache[support_key] = support_metrics

                score_pack = self.simulate_and_score(
                    rotated_coords,
                    self.real_afm_nm,
                    meta=meta,
                    tip=None,
                    lowpass=None,
                    foreground_pose=True,
                    estimate_foreground_translation=find_translation,
                )
                if score_pack is None:
                    result = {
                        'rx': nrx, 'ry': nry, 'rz': nrz, 'tx': ntx, 'ty': nty,
                        'score': -1e9, 'dx': 0.0, 'dy': 0.0, 'rmsd': None, 'zncc': None,
                        'foreground_zncc': None, 'foreground_dice': None,
                        'image_score': -1e9,
                        'support_ratio': (
                            support_metrics.get("support_ratio")
                            if isinstance(support_metrics, dict)
                            else None
                        ),
                        'face_quality_ratio': (
                            support_metrics.get("face_quality_ratio")
                            if isinstance(support_metrics, dict)
                            else None
                        ),
                        'support_face_rank': support_face_rank,
                        'support_contact_area_A2': (
                            support_metrics.get("contact_area_A2")
                            if isinstance(support_metrics, dict)
                            else None
                        ),
                        '_support_face': support_face,
                    }
                else:
                    image_score = score_pack.get(
                        'pose_score',
                        score_pack.get('score', -1e9),
                    )
                    objective_score = image_score
                    if substrate_constrained:
                        if isinstance(support_metrics, dict):
                            objective_score = (
                                self._substrate_constrained_pose_score(
                                    image_score,
                                    support_metrics.get("support_ratio"),
                                    support_metrics.get("face_quality_ratio"),
                                    support_metrics.get("height_ratio", 1.0),
                                )
                            )
                        else:
                            objective_score = -1e9
                    result = {
                        'rx': nrx, 'ry': nry, 'rz': nrz,
                        'tx': ntx, 'ty': nty,
                        'score': objective_score,
                        'image_score': image_score,
                        'dx': score_pack.get('dx', 0.0),
                        'dy': score_pack.get('dy', 0.0),
                        'rmsd': score_pack.get('rmsd'),
                        'zncc': score_pack.get('zncc'),
                        'residual_score': score_pack.get('residual_score', -1e9),
                        'residual_rmsd': score_pack.get('residual_rmsd'),
                        'residual_zncc': score_pack.get('residual_zncc'),
                        'foreground_zncc': score_pack.get('foreground_zncc'),
                        'foreground_dice': score_pack.get('foreground_dice'),
                        'support_ratio': (
                            support_metrics.get("support_ratio")
                            if isinstance(support_metrics, dict)
                            else None
                        ),
                        'face_quality_ratio': (
                            support_metrics.get("face_quality_ratio")
                            if isinstance(support_metrics, dict)
                            else None
                        ),
                        'support_face_rank': support_face_rank,
                        'support_contact_area_A2': (
                            support_metrics.get("contact_area_A2")
                            if isinstance(support_metrics, dict)
                            else None
                        ),
                        'support_height_ratio': (
                            support_metrics.get("height_ratio")
                            if isinstance(support_metrics, dict)
                            else None
                        ),
                        '_support_face': support_face,
                    }
                eval_cache[key] = result
                eval_count += 1
                progress.setValue(min(eval_count, int(max_eval_est)))
                rmsd_text = f"{best['rmsd']:.3f} nm" if best.get('rmsd') is not None else "-"
                overlap_text = (
                    f"{100.0 * best['foreground_dice']:.1f}%"
                    if best.get('foreground_dice') is not None
                    else "-"
                )
                support_text = (
                    f"{100.0 * best['support_ratio']:.1f}% "
                    f"(face #{best.get('support_face_rank', '-')})"
                    if best.get("support_ratio") is not None
                    else "-"
                )
                progress.setLabelText(
                    f"Estimating pose ({selected_level}, {search_mode})...\n"
                    f"Rotation axes: {axes_text}\n"
                    f"XY center: ({best.get('tx', orig_tx):.2f}, {best.get('ty', orig_ty):.2f}) nm\n"
                    f"Evaluations: {eval_count}\n"
                    f"Best RMSD: {rmsd_text}    Foreground overlap: {overlap_text}\n"
                    f"Substrate contact retained: {support_text}\n"
                    f"Foreground pose score: {best['score']:.4f}"
                )
                QApplication.processEvents()
                if progress.wasCanceled():
                    cancel_requested = True
                return result

            coarse_candidates = []

            def remember_coarse(candidate):
                if candidate is None:
                    return
                coarse_candidates.append(dict(candidate))
                maybe_update_best(candidate)

            # Global search starts every rotation candidate with the model XY
            # centroid at the center of the Real AFM image. Translation is then
            # introduced by molecular-foreground centroids and local XY search.
            # Refine mode preserves the previously estimated/current placement.
            if refine_current and not compare_ranked_faces:
                start_tx, start_ty = orig_tx, orig_ty
            else:
                start_tx, start_ty = None, None

            # Baseline: current rotation (always evaluated first).
            base = evaluate(
                orig_rx,
                orig_ry,
                orig_rz,
                start_tx,
                start_ty,
                find_translation=True,
                support_face=active_support_face,
            )
            remember_coarse(base)
            remember_coarse(residual_center_candidate(base))

            def angle_delta(a, b):
                return abs(self.normalize_angle(float(a) - float(b)))

            def within_refine_bounds(rx, ry, rz):
                if angle_delta(rx, orig_rx) > max_tilt_dev + 1e-9:
                    return False
                if angle_delta(ry, orig_ry) > max_tilt_dev + 1e-9:
                    return False
                if max_z_dev is not None and angle_delta(rz, orig_rz) > max_z_dev + 1e-9:
                    return False
                return True

            def within_start_tilt_bounds(rx, ry, start_pose):
                """Limit out-of-plane drift from one ranked-face refine seed."""
                if angle_delta(rx, start_pose["rx"]) > max_tilt_dev + 1e-9:
                    return False
                if angle_delta(ry, start_pose["ry"]) > max_tilt_dev + 1e-9:
                    return False
                return True

            def within_local_pose_bounds(rx, ry, rz, tx, ty):
                """Bound Refine current pose: fixed X/Y tilt, small Z + tip XY."""
                try:
                    if angle_delta(rx, orig_rx) > 1e-4:
                        return False
                    if angle_delta(ry, orig_ry) > 1e-4:
                        return False
                    if angle_delta(rz, orig_rz) > (
                        float(cfg["max_local_rotation_dev_deg"]) + 1e-9
                    ):
                        return False
                    max_shift_px = float(cfg["max_local_shift_px"])
                    if abs(float(tx) - orig_tx) > (
                        max_shift_px * pixel_x_nm + 1e-9
                    ):
                        return False
                    if abs(float(ty) - orig_ty) > (
                        max_shift_px * pixel_y_nm + 1e-9
                    ):
                        return False
                    return True
                except Exception:
                    return False

            # Stage 1:
            # - Global search: coarse X/Y seeds + Z grid
            # - Preserve-plane refine (Find Initial Plane): keep X/Y, coarse Z only
            # - Local pose refine: skip coarse seeding (current pose only)
            if compare_ranked_faces:
                for support_face in support_faces:
                    if cancel_requested:
                        break
                    for inplane_angle in preserve_z_coarse:
                        if cancel_requested:
                            break
                        seed_rx, seed_ry, seed_rz = (
                            support_face_seed_euler(
                                support_face,
                                inplane_angle,
                            )
                        )
                        if not allowed_axes.get('X', True):
                            seed_rx = orig_rx
                        if not allowed_axes.get('Y', True):
                            seed_ry = orig_ry
                        if not allowed_axes.get('Z', True):
                            seed_rz = orig_rz
                        cand = evaluate(
                            seed_rx,
                            seed_ry,
                            seed_rz,
                            start_tx,
                            start_ty,
                            find_translation=True,
                            support_face=support_face,
                        )
                        if cand is None:
                            break
                        remember_coarse(cand)
                        remember_coarse(residual_center_candidate(cand))
            elif not refine_current:
                for off_x, off_y in cfg["seed_offsets"]:
                    if cancel_requested:
                        break
                    sx = self.normalize_angle(orig_rx + off_x) if allowed_axes.get('X', True) else orig_rx
                    sy = self.normalize_angle(orig_ry + off_y) if allowed_axes.get('Y', True) else orig_ry
                    for zc in z_coarse:
                        if cancel_requested:
                            break
                        cand = evaluate(
                            sx,
                            sy,
                            zc,
                            start_tx,
                            start_ty,
                            find_translation=True,
                            support_face=active_support_face,
                        )
                        if cand is None:
                            break
                        remember_coarse(cand)
                        remember_coarse(residual_center_candidate(cand))
            elif (
                preserve_plane
                and not (refine_current and refine_kind == "local_pose")
                and allowed_axes.get('Z', True)
            ):
                for zc in preserve_z_coarse:
                    if cancel_requested:
                        break
                    cand = evaluate(
                        orig_rx,
                        orig_ry,
                        float(zc),
                        start_tx,
                        start_ty,
                        find_translation=True,
                        support_face=active_support_face,
                    )
                    if cand is None:
                        break
                    remember_coarse(cand)
                    remember_coarse(residual_center_candidate(cand))

            # Stage 2: refine several distinct coarse solutions for a global
            # search, or just the current/preserved-plane best for refinement.
            if refine_current:
                refine_starts = [dict(best)]
            else:
                coarse_candidates.sort(key=lambda item: item.get('score', -1e9), reverse=True)
                refine_starts = []
                for candidate in coarse_candidates:
                    distinct = all(
                        abs(self.normalize_angle(candidate['rx'] - old['rx'])) >= 8.0
                        or abs(self.normalize_angle(candidate['ry'] - old['ry'])) >= 8.0
                        or abs(self.normalize_angle(candidate['rz'] - old['rz'])) >= 8.0
                        for old in refine_starts
                    )
                    if distinct:
                        refine_starts.append(dict(candidate))
                    if len(refine_starts) >= int(cfg.get("refine_start_count", 4)):
                        break
            if not refine_starts:
                refine_starts = [dict(best)]

            xy_refine_steps = tuple(cfg.get("xy_refine_steps_px", (8.0, 4.0, 2.0, 1.0)))
            for start in refine_starts:
                local_best = dict(start)
                for step_idx, step in enumerate(active_refine_steps):
                    if cancel_requested:
                        break
                    xy_step_px = float(xy_refine_steps[min(step_idx, len(xy_refine_steps) - 1)])
                    tx_step_nm = max(0.2, pixel_x_nm * xy_step_px)
                    ty_step_nm = max(0.2, pixel_y_nm * xy_step_px)
                    # Preserve-plane refine: keep X/Y steps small relative to Z.
                    tilt_step = float(step)
                    z_step_local = (
                        # Coarse Z spacing must not remain a permanent lower
                        # bound: Medium previously stopped at 10 degrees and
                        # could not correct an obviously visible in-plane error.
                        max(float(step) * 2.0, 0.5)
                        if preserve_plane else float(step)
                    )
                    for _ in range(int(cfg["max_refine_iter"])):
                        if cancel_requested:
                            break
                        center = local_best
                        candidates = []
                        def append_rotation_candidate(axis, delta):
                            # local_pose: keep X/Y Euler fixed and nudge Z only.
                            use_substrate_lab = (
                                substrate_constrained
                                and not (
                                    refine_current
                                    and refine_kind == "local_pose"
                                )
                            )
                            if use_substrate_lab:
                                candidate_rx, candidate_ry, candidate_rz = (
                                    substrate_lab_axis_candidate(
                                        center,
                                        axis,
                                        delta,
                                    )
                                )
                            else:
                                candidate_rx = float(center['rx'])
                                candidate_ry = float(center['ry'])
                                candidate_rz = float(center['rz'])
                                if axis == 'X':
                                    candidate_rx += float(delta)
                                elif axis == 'Y':
                                    candidate_ry += float(delta)
                                else:
                                    candidate_rz += float(delta)
                            candidates.append((
                                candidate_rx,
                                candidate_ry,
                                candidate_rz,
                                center['tx'],
                                center['ty'],
                                center.get('_support_face'),
                            ))

                        if allowed_axes.get('X', True) and not (
                            refine_current and refine_kind == "local_pose"
                        ):
                            append_rotation_candidate('X', tilt_step)
                            append_rotation_candidate('X', -tilt_step)
                        if allowed_axes.get('Y', True) and not (
                            refine_current and refine_kind == "local_pose"
                        ):
                            append_rotation_candidate('Y', tilt_step)
                            append_rotation_candidate('Y', -tilt_step)
                        if allowed_axes.get('Z', True):
                            append_rotation_candidate('Z', z_step_local)
                            append_rotation_candidate('Z', -z_step_local)
                        candidates.extend([
                            (center['rx'], center['ry'], center['rz'], center['tx'] + tx_step_nm, center['ty'], center.get('_support_face')),
                            (center['rx'], center['ry'], center['rz'], center['tx'] - tx_step_nm, center['ty'], center.get('_support_face')),
                            (center['rx'], center['ry'], center['rz'], center['tx'], center['ty'] + ty_step_nm, center.get('_support_face')),
                            (center['rx'], center['ry'], center['rz'], center['tx'], center['ty'] - ty_step_nm, center.get('_support_face')),
                        ])
                        improved = False
                        for crx, cry, crz, ctx, cty, candidate_face in candidates:
                            if cancel_requested:
                                break
                            if refine_current and refine_kind == "local_pose":
                                if not within_local_pose_bounds(
                                    crx,
                                    cry,
                                    crz,
                                    ctx,
                                    cty,
                                ):
                                    continue
                            elif substrate_constrained:
                                # Ranked-face seeds differ from the original
                                # Euler angles, so bound tilt to each refine
                                # start instead of disabling the limit.
                                if not within_start_tilt_bounds(
                                    crx,
                                    cry,
                                    start,
                                ):
                                    continue
                            elif (
                                refine_current
                                and not within_refine_bounds(crx, cry, crz)
                            ):
                                continue
                            cand = evaluate(
                                crx,
                                cry,
                                crz,
                                ctx,
                                cty,
                                support_face=candidate_face,
                            )
                            if cand is None:
                                break
                            if cand['score'] > (local_best['score'] + 1e-6):
                                local_best = dict(cand)
                                improved = True
                            maybe_update_best(cand)
                        if not improved:
                            break
                maybe_update_best(local_best)

            if cancel_requested:
                self.set_rotation_controls_xyz(orig_rx, orig_ry, orig_rz, apply_transform=True, trigger_simulation=False)
                self._set_tip_center_xy_nm(orig_tx, orig_ty, update=False)
                self._set_tip_z_nm(orig_tz, update=True)
                QMessageBox.information(self, "Pose", "Pose estimation canceled.")
                return

            if best['score'] <= -1e8:
                self.set_rotation_controls_xyz(orig_rx, orig_ry, orig_rz, apply_transform=True, trigger_simulation=False)
                self._set_tip_center_xy_nm(orig_tx, orig_ty, update=False)
                self._set_tip_z_nm(orig_tz, update=True)
                QMessageBox.warning(self, "Pose", "Pose estimation failed.")
                return

            self.set_rotation_controls_xyz(
                best['rx'], best['ry'], best['rz'],
                apply_transform=True,
                trigger_simulation=False,
            )
            self._ensure_tip_xy_range_for_scan(scan_x_nm, scan_y_nm)
            best_tx, best_ty = self._set_tip_center_xy_nm(best['tx'], best['ty'], update=False)
            self._set_tip_z_nm(orig_tz, update=True)
            final_pack = self._simulate_xy_for_real_afm(
                update_panels=True,
                store_results=True,
                check_busy=False,
                show_messages=False,
            )
            if final_pack is None:
                self.set_rotation_controls_xyz(orig_rx, orig_ry, orig_rz, apply_transform=True, trigger_simulation=False)
                self._set_tip_center_xy_nm(orig_tx, orig_ty, update=False)
                self._set_tip_z_nm(orig_tz, update=True)
                QMessageBox.warning(self, "Pose", "Failed to generate final simulated image.")
                return

            final_meta = final_pack.get("meta") or {}
            final_sim_for_pose = self._sim_map_for_pose_scoring(
                final_pack.get("raw"),
                final_meta.get("scan_x_nm"),
                final_meta.get("scan_y_nm"),
                final_meta.get("nx"),
                final_meta.get("ny"),
            )
            # Keep substrate-contact scoring and the rotation search exactly as
            # selected above. Only after the winning physical pose is fixed,
            # maximize non-wrapping image correlation to remove the remaining
            # XY translation.
            final_image_alignment = (
                self._final_pose_image_correlation_alignment(
                    self.real_afm_nm,
                    final_sim_for_pose,
                )
            )
            correlation_applied_dx_px = 0.0
            correlation_applied_dy_px = 0.0
            before_image_correlation = -1e9
            after_image_correlation = -1e9
            if isinstance(final_image_alignment, dict):
                correlation_dx_px = float(
                    final_image_alignment.get("dx_px", 0.0)
                )
                correlation_dy_px = float(
                    final_image_alignment.get("dy_px", 0.0)
                )
                before_image_correlation = float(
                    final_image_alignment.get(
                        "zero_shift_correlation",
                        -1e9,
                    )
                )
                after_image_correlation = before_image_correlation
                if (
                    abs(correlation_dx_px) >= 0.25
                    or abs(correlation_dy_px) >= 0.25
                ):
                    candidate_tx, candidate_ty = (
                        self._set_tip_center_xy_nm(
                            best_tx - correlation_dx_px * pixel_x_nm,
                            best_ty - correlation_dy_px * pixel_y_nm,
                            update=True,
                        )
                    )
                    candidate_pack = self._simulate_xy_for_real_afm(
                        update_panels=False,
                        store_results=False,
                        check_busy=False,
                        show_messages=False,
                    )
                    candidate_sim_for_pose = None
                    candidate_image_alignment = None
                    if candidate_pack is not None:
                        candidate_meta = candidate_pack.get("meta") or {}
                        candidate_sim_for_pose = (
                            self._sim_map_for_pose_scoring(
                                candidate_pack.get("raw"),
                                candidate_meta.get("scan_x_nm"),
                                candidate_meta.get("scan_y_nm"),
                                candidate_meta.get("nx"),
                                candidate_meta.get("ny"),
                            )
                        )
                        candidate_image_alignment = (
                            self._final_pose_image_correlation_alignment(
                                self.real_afm_nm,
                                candidate_sim_for_pose,
                            )
                        )
                    after_image_correlation = (
                        float(candidate_image_alignment.get(
                            "zero_shift_correlation",
                        ))
                        if isinstance(candidate_image_alignment, dict)
                        else -1e9
                    )
                    if (
                        candidate_sim_for_pose is not None
                        and np.isfinite(after_image_correlation)
                        and after_image_correlation
                        > before_image_correlation + 1e-4
                    ):
                        best_tx = float(candidate_tx)
                        best_ty = float(candidate_ty)
                        correlation_applied_dx_px = correlation_dx_px
                        correlation_applied_dy_px = correlation_dy_px
                        final_pack = candidate_pack
                        final_sim_for_pose = candidate_sim_for_pose
                        stored_final_pack = self._simulate_xy_for_real_afm(
                            update_panels=True,
                            store_results=True,
                            check_busy=False,
                            show_messages=False,
                        )
                        if stored_final_pack is not None:
                            final_pack = stored_final_pack
                            final_meta = final_pack.get("meta") or {}
                            final_sim_for_pose = (
                                self._sim_map_for_pose_scoring(
                                    final_pack.get("raw"),
                                    final_meta.get("scan_x_nm"),
                                    final_meta.get("scan_y_nm"),
                                    final_meta.get("nx"),
                                    final_meta.get("ny"),
                                )
                            )
                    else:
                        self._set_tip_center_xy_nm(
                            best_tx,
                            best_ty,
                            update=True,
                        )
                        after_image_correlation = before_image_correlation

            # Once XY is aligned, refine only the in-plane rotation. For a
            # substrate-constrained pose this is a laboratory-Z rotation, so
            # the selected support face and its contact geometry are preserved.
            final_z_delta_deg = 0.0
            final_z_correlation_before = after_image_correlation
            final_z_correlation_after = after_image_correlation
            if allowed_axes.get("Z", True):
                z_start = {
                    "rx": float(best["rx"]),
                    "ry": float(best["ry"]),
                    "rz": float(best["rz"]),
                    "lab_z_delta": 0.0,
                    "correlation": -1e9,
                    "alignment": None,
                }
                current_z_alignment = (
                    self._final_pose_image_correlation_alignment(
                        self.real_afm_nm,
                        final_sim_for_pose,
                    )
                )
                if isinstance(current_z_alignment, dict):
                    z_start["correlation"] = float(
                        current_z_alignment.get("correlation", -1e9)
                    )
                    z_start["alignment"] = current_z_alignment
                    final_z_correlation_before = float(
                        current_z_alignment.get(
                            "zero_shift_correlation",
                            after_image_correlation,
                        )
                    )
                    final_z_correlation_after = (
                        final_z_correlation_before
                    )

                def evaluate_final_z_only(center, delta_deg):
                    cumulative_delta = (
                        float(center["lab_z_delta"])
                        + float(delta_deg)
                    )
                    if abs(cumulative_delta) > (
                        float(cfg["max_final_z_change_deg"]) + 1e-9
                    ):
                        return None
                    # local_pose keeps X/Y Euler fixed; lab-Z about the
                    # substrate can tilt those axes, so use plain Euler Z.
                    use_substrate_lab = (
                        substrate_constrained
                        and not (
                            refine_current
                            and refine_kind == "local_pose"
                        )
                    )
                    if use_substrate_lab:
                        crx, cry, crz = substrate_lab_axis_candidate(
                            center,
                            "Z",
                            delta_deg,
                        )
                    else:
                        crx = float(center["rx"])
                        cry = float(center["ry"])
                        crz = self.normalize_angle(
                            float(center["rz"]) + float(delta_deg)
                        )
                    if (
                        refine_current
                        and refine_kind == "local_pose"
                        and not within_local_pose_bounds(
                            crx,
                            cry,
                            crz,
                            best_tx,
                            best_ty,
                        )
                    ):
                        return None
                    self.set_rotation_controls_xyz(
                        crx,
                        cry,
                        crz,
                        apply_transform=True,
                        trigger_simulation=False,
                    )
                    self._set_tip_center_xy_nm(
                        best_tx,
                        best_ty,
                        update=True,
                    )
                    candidate_pack = self._simulate_xy_for_real_afm(
                        update_panels=False,
                        store_results=False,
                        check_busy=False,
                        show_messages=False,
                    )
                    if candidate_pack is None:
                        return None
                    candidate_meta = candidate_pack.get("meta") or {}
                    candidate_sim = self._sim_map_for_pose_scoring(
                        candidate_pack.get("raw"),
                        candidate_meta.get("scan_x_nm"),
                        candidate_meta.get("scan_y_nm"),
                        candidate_meta.get("nx"),
                        candidate_meta.get("ny"),
                    )
                    candidate_alignment = (
                        self._final_pose_image_correlation_alignment(
                            self.real_afm_nm,
                            candidate_sim,
                        )
                    )
                    if not isinstance(candidate_alignment, dict):
                        return None
                    correlation = float(
                        candidate_alignment.get("correlation", -1e9)
                    )
                    if not np.isfinite(correlation):
                        return None
                    return {
                        "rx": float(crx),
                        "ry": float(cry),
                        "rz": float(crz),
                        "lab_z_delta": float(cumulative_delta),
                        "correlation": correlation,
                        "alignment": candidate_alignment,
                    }

                z_best = dict(z_start)
                if np.isfinite(float(z_best["correlation"])):
                    for z_step_deg in cfg["final_z_steps_deg"]:
                        for _ in range(2):
                            z_candidates = [
                                evaluate_final_z_only(
                                    z_best,
                                    float(z_step_deg),
                                ),
                                evaluate_final_z_only(
                                    z_best,
                                    -float(z_step_deg),
                                ),
                            ]
                            z_candidates = [
                                candidate
                                for candidate in z_candidates
                                if isinstance(candidate, dict)
                            ]
                            if not z_candidates:
                                break
                            z_candidate = max(
                                z_candidates,
                                key=lambda candidate: float(
                                    candidate["correlation"]
                                ),
                            )
                            if float(z_candidate["correlation"]) <= (
                                float(z_best["correlation"]) + 1e-4
                            ):
                                break
                            z_best = dict(z_candidate)

                # Candidate evaluation leaves the controls at the last trial.
                # Restore the selected Z state before applying its final XY
                # correlation shift.
                self.set_rotation_controls_xyz(
                    z_best["rx"],
                    z_best["ry"],
                    z_best["rz"],
                    apply_transform=True,
                    trigger_simulation=False,
                )
                self._set_tip_center_xy_nm(
                    best_tx,
                    best_ty,
                    update=True,
                )
                if (
                    abs(float(z_best["lab_z_delta"])) >= 0.05
                    and isinstance(z_best.get("alignment"), dict)
                ):
                    z_dx_px = float(
                        z_best["alignment"].get("dx_px", 0.0)
                    )
                    z_dy_px = float(
                        z_best["alignment"].get("dy_px", 0.0)
                    )
                    candidate_tx, candidate_ty = (
                        self._set_tip_center_xy_nm(
                            best_tx - z_dx_px * pixel_x_nm,
                            best_ty - z_dy_px * pixel_y_nm,
                            update=True,
                        )
                    )
                    z_final_pack = self._simulate_xy_for_real_afm(
                        update_panels=False,
                        store_results=False,
                        check_busy=False,
                        show_messages=False,
                    )
                    z_final_sim = None
                    z_final_alignment = None
                    if z_final_pack is not None:
                        z_final_meta = z_final_pack.get("meta") or {}
                        z_final_sim = self._sim_map_for_pose_scoring(
                            z_final_pack.get("raw"),
                            z_final_meta.get("scan_x_nm"),
                            z_final_meta.get("scan_y_nm"),
                            z_final_meta.get("nx"),
                            z_final_meta.get("ny"),
                        )
                        z_final_alignment = (
                            self._final_pose_image_correlation_alignment(
                                self.real_afm_nm,
                                z_final_sim,
                            )
                        )
                    z_zero_shift_correlation = (
                        float(z_final_alignment.get(
                            "zero_shift_correlation",
                            -1e9,
                        ))
                        if isinstance(z_final_alignment, dict)
                        else -1e9
                    )
                    if (
                        z_final_sim is not None
                        and np.isfinite(z_zero_shift_correlation)
                        and z_zero_shift_correlation
                        > final_z_correlation_before + 1e-4
                    ):
                        best["rx"] = float(z_best["rx"])
                        best["ry"] = float(z_best["ry"])
                        best["rz"] = float(z_best["rz"])
                        best_tx = float(candidate_tx)
                        best_ty = float(candidate_ty)
                        final_z_delta_deg = float(
                            z_best["lab_z_delta"]
                        )
                        final_z_correlation_after = (
                            z_zero_shift_correlation
                        )
                        correlation_applied_dx_px += z_dx_px
                        correlation_applied_dy_px += z_dy_px
                        after_image_correlation = (
                            z_zero_shift_correlation
                        )
                        final_pack = z_final_pack
                        final_sim_for_pose = z_final_sim
                        stored_final_pack = self._simulate_xy_for_real_afm(
                            update_panels=True,
                            store_results=True,
                            check_busy=False,
                            show_messages=False,
                        )
                        if stored_final_pack is not None:
                            final_pack = stored_final_pack
                            final_meta = final_pack.get("meta") or {}
                            final_sim_for_pose = (
                                self._sim_map_for_pose_scoring(
                                    final_pack.get("raw"),
                                    final_meta.get("scan_x_nm"),
                                    final_meta.get("scan_y_nm"),
                                    final_meta.get("nx"),
                                    final_meta.get("ny"),
                                )
                            )
                    else:
                        self.set_rotation_controls_xyz(
                            best["rx"],
                            best["ry"],
                            best["rz"],
                            apply_transform=True,
                            trigger_simulation=False,
                        )
                        self._set_tip_center_xy_nm(
                            best_tx,
                            best_ty,
                            update=True,
                        )

            final_metrics = self._compute_comparison_metrics(
                self.real_afm_nm, final_sim_for_pose, dx=0.0, dy=0.0
            )
            final_explicit_metrics = dict(final_metrics)
            final_foreground_metrics = {}
            try:
                final_foreground_metrics = self._score_pose_foreground_on_real_grid(
                    self.real_afm_nm,
                    final_sim_for_pose,
                )
            except Exception:
                pass
            self.pose = {
                'theta_deg': 0.0,
                # XY placement is represented once, by the scan center. Keeping
                # a second display-only residual made Sim/overlay positions diverge.
                'dx_px': 0.0,
                'dy_px': 0.0,
                'score': float(final_metrics['score']),
                'estimated': True,
                'rmsd_nm': final_metrics.get('rmsd'),
                'zncc': final_metrics.get('zncc'),
                'mirror_mode': 'none',
                'rot_x_deg': float(best['rx']),
                'rot_y_deg': float(best['ry']),
                'rot_z_deg': float(best['rz']),
                'center_x_nm': float(best_tx),
                'center_y_nm': float(best_ty),
                'shift_x_nm': float(best_tx - orig_tx),
                'shift_y_nm': float(best_ty - orig_ty),
                'final_correlation_dx_px': float(
                    correlation_applied_dx_px
                ),
                'final_correlation_dy_px': float(
                    correlation_applied_dy_px
                ),
                'final_correlation_before': float(
                    before_image_correlation
                ),
                'final_correlation_after': float(
                    after_image_correlation
                ),
                'final_z_delta_deg': float(final_z_delta_deg),
                'final_z_correlation_before': float(
                    final_z_correlation_before
                ),
                'final_z_correlation_after': float(
                    final_z_correlation_after
                ),
                'explicit_rmsd_nm': final_explicit_metrics.get('rmsd'),
                'explicit_zncc': final_explicit_metrics.get('zncc'),
                'foreground_score': final_foreground_metrics.get('score'),
                'foreground_zncc': final_foreground_metrics.get(
                    'foreground_zncc'
                ),
                'foreground_dice': final_foreground_metrics.get(
                    'foreground_dice'
                ),
                'centroid_distance_fraction': final_foreground_metrics.get(
                    'centroid_distance_fraction'
                ),
                'rotation_axes': dict(allowed_axes),
                'search_mode': search_mode,
                'precision': selected_level,
                'refine_kind': refine_kind,
                'objective_score': float(best.get('score', -1e9)),
                'image_pose_score': best.get('image_score'),
                'support_face_rank': best.get('support_face_rank'),
                'support_ratio': best.get('support_ratio'),
                'support_face_quality_ratio': best.get(
                    'face_quality_ratio'
                ),
                'support_contact_area_A2': best.get(
                    'support_contact_area_A2'
                ),
                'support_height_ratio': best.get('support_height_ratio'),
            }
            self.pose_seed_from_initial_plane = False
            if best.get('support_face_rank') is not None:
                self.pose_support_active_face_rank = int(
                    best['support_face_rank']
                )
            self._store_pose_for_active_structure(self.pose)

            # The final explicit pose is now known. Redraw both consumers so
            # Sim Aligned and Difference cannot show different pose generations.
            try:
                self._refresh_sim_aligned_panel()
            except Exception:
                pass
            try:
                self._update_difference_panel()
            except Exception:
                pass

            self._enable_impose_model_after_pose()
            try:
                self._ensure_tip_xy_range_for_scan(scan_x_nm, scan_y_nm)
            except Exception:
                pass
            # Estimate Pose only searches Rotation XYZ + tip XY. Tip Z is a
            # 3D display parameter and must remain at the pre-estimate value.
            self._set_tip_z_nm(orig_tz, update=True)

            final_rmsd = final_metrics.get('rmsd')
            final_zncc = final_metrics.get('zncc')
            rmsd_line = f"RMSD: {final_rmsd:.3f} nm\n" if final_rmsd is not None else ""
            zncc_line = f"ZNCC: {final_zncc:.3f}\n" if final_zncc is not None else ""
            foreground_dice = final_foreground_metrics.get('foreground_dice')
            foreground_line = (
                f"Foreground overlap: {100.0 * foreground_dice:.1f}%\n"
                if foreground_dice is not None
                else ""
            )
            correlation_line = (
                "Final image-correlation shift: "
                f"({correlation_applied_dx_px:+.2f}, "
                f"{correlation_applied_dy_px:+.2f}) px\n"
                f"Image correlation: {before_image_correlation:.3f}"
                f" -> {after_image_correlation:.3f}\n"
                if before_image_correlation > -1e8
                else ""
            )
            final_z_line = (
                "Final substrate-Z refinement: "
                f"{final_z_delta_deg:+.2f} deg\n"
                f"Z-refinement correlation: "
                f"{final_z_correlation_before:.3f}"
                f" -> {final_z_correlation_after:.3f}\n"
                if final_z_correlation_before > -1e8
                else ""
            )
            support_ratio = best.get('support_ratio')
            support_line = (
                f"Substrate face: #{best.get('support_face_rank')}\n"
                f"Contact retained: {100.0 * support_ratio:.1f}%\n"
                if support_ratio is not None
                else ""
            )

            poor_fit = self._pose_fit_is_poor(
                rmsd_nm=final_rmsd,
                zncc=final_zncc,
                foreground_score=final_foreground_metrics.get('score'),
            )

            QMessageBox.information(
                self, "Pose Estimated",
                f"RotX: {best['rx']:.2f} deg\n"
                f"RotY: {best['ry']:.2f} deg\n"
                f"RotZ: {best['rz']:.2f} deg\n"
                f"Center X: {best_tx:.2f} nm\n"
                f"Center Y: {best_ty:.2f} nm\n"
                f"Shift X: {best_tx - orig_tx:+.2f} nm\n"
                f"Shift Y: {best_ty - orig_ty:+.2f} nm\n"
                f"Residual Dx: {final_metrics['dx']:.2f} px\n"
                f"Residual Dy: {final_metrics['dy']:.2f} px\n"
                f"{rmsd_line}"
                f"{zncc_line}"
                f"{foreground_line}"
                f"{correlation_line}"
                f"{final_z_line}"
                f"{support_line}"
                f"Evaluations: {eval_count}\n"
                f"Rotation axes: {axes_text}\n"
                f"Precision: {selected_level}\n"
                f"Search mode: {search_mode}"
                + ("\n\nNote: the fit is still weak. Left-drag the Real AFM panel "
                   "to select a tight ROI around one molecule, rerun Medium "
                   "(Global search), then try Auto-fit Tip Radius + Angle."
                   if poor_fit else "")
            )
        finally:
            try:
                progress.setValue(int(max_eval_est))
                progress.close()
            except Exception:
                pass
            self._pose_estimation_running = False
            try:
                self._update_model_overlay()
            except Exception:
                pass
            QApplication.restoreOverrideCursor()

    def get_simulated_image_for_real_afm(self):
        """Generate simulated XY image matching Real AFM scan size/resolution."""
        result = self._simulate_xy_for_real_afm(
            update_panels=True,
            store_results=True,
            check_busy=True,
            show_messages=True,
        )
        if result is None:
            return

    def _set_pose_rotation_axis(self, axis, checked):
        """Store which Rotation XYZ axes Estimate Pose is allowed to change."""
        if not hasattr(self, 'pose_rotation_axes') or not isinstance(self.pose_rotation_axes, dict):
            self.pose_rotation_axes = {'X': True, 'Y': True, 'Z': True}
        axis_key = str(axis).upper()
        if axis_key in ('X', 'Y', 'Z'):
            self.pose_rotation_axes[axis_key] = bool(checked)

    def _get_pose_rotation_axes(self):
        """Return allowed Estimate Pose axes from the Real AFM window checkboxes."""
        axes = dict(getattr(self, 'pose_rotation_axes', {'X': True, 'Y': True, 'Z': True}) or {})
        for axis in ('X', 'Y', 'Z'):
            axes.setdefault(axis, True)
        checks = getattr(self, 'pose_axis_checks', {}) or {}
        for axis, check in checks.items():
            try:
                axis_key = str(axis).upper()
                if axis_key in ('X', 'Y', 'Z'):
                    axes[axis_key] = bool(check.isChecked())
            except Exception:
                pass
        self.pose_rotation_axes = {axis: bool(axes.get(axis, True)) for axis in ('X', 'Y', 'Z')}
        return dict(self.pose_rotation_axes)

    def _on_impose_model_toggled(self, checked):
        """Toggle the model overlay without changing pose or scan placement."""
        self.impose_model_enabled = bool(checked)
        if checked:
            if self.atoms_data is None:
                QMessageBox.information(self, "Impose model", "PDB/structure is not loaded.")
            self._ensure_real_afm_window(show=False)
        timer = getattr(self, '_model_overlay_update_timer', None)
        if timer is not None:
            try:
                timer.stop()
            except Exception:
                pass
        self._update_model_overlay(force=True)

    def _enable_impose_model_after_pose(self):
        """Turn on Impose model after a successful Estimate Pose."""
        self._ensure_real_afm_window(show=False)
        check = getattr(self, "impose_model_check", None)
        if check is not None:
            try:
                if not check.isChecked():
                    check.setChecked(True)
                    return
            except RuntimeError:
                self.impose_model_check = None
        self.impose_model_enabled = True
        try:
            self._update_model_overlay(force=True)
        except Exception:
            pass

    def _on_impose_opacity_changed(self, value):
        """Update overlay opacity from the slider (10-100 -> 0.1-1.0)."""
        try:
            self.impose_model_opacity = max(0.0, min(1.0, float(value) / 100.0))
        except Exception:
            self.impose_model_opacity = 0.6
        view = getattr(self, 'real_afm_window_view', None)
        if view is not None:
            try:
                view.setModelOverlayOpacity(self.impose_model_opacity)
            except Exception:
                pass

    def _get_real_afm_view(self):
        """Return the _AspectPixmapView of the Real AFM panel (re-find if needed)."""
        frame = getattr(self, 'real_afm_window_real_frame', None)
        view = None
        if frame is not None:
            try:
                view = frame.findChild(_AspectPixmapView, "afm_image_view")
            except Exception:
                view = None
        if view is None:
            cached = getattr(self, 'real_afm_window_view', None)
            try:
                if cached is not None and not cached.isHidden():
                    _ = cached.width()
                    view = cached
            except RuntimeError:
                view = None
        self.real_afm_window_view = view
        if view is None:
            print("[WARNING] Impose model: Real AFM view widget not found")
        return view

    def _vtk_overlay_signature(self):
        """Settings that require rebuilding hidden VTK actors used for Impose model."""
        style = self.style_combo.currentText() if hasattr(self, 'style_combo') else ""
        size = self.size_slider.value() if hasattr(self, 'size_slider') else 100
        opacity = self.opacity_slider.value() if hasattr(self, 'opacity_slider') else 100
        quality = self.quality_combo.currentText() if hasattr(self, 'quality_combo') else ""
        atom_filter = self.atom_combo.currentText() if hasattr(self, 'atom_combo') else ""
        color = self.color_combo.currentText() if hasattr(self, 'color_combo') else ""
        return (style, size, opacity, quality, atom_filter, color, self.current_structure_path)

    def _build_vtk_molecule_actors(self):
        """Build/update VTK sample/bond actors from current UI settings."""
        self._ensure_vtk_initialized()
        if not hasattr(self, 'renderer') or self.renderer is None:
            return False

        if self.sample_actor:
            self.renderer.RemoveActor(self.sample_actor)
        if self.bonds_actor:
            self.renderer.RemoveActor(self.bonds_actor)

        x, y, z, elements, chain_ids, b_factors, mask = self.get_filtered_atoms()
        if x is None:
            return False

        style = self.style_combo.currentText()
        size_factor = self.size_slider.value() / 100.0
        opacity = self.opacity_slider.value() / 100.0
        quality = self.quality_combo.currentText()

        if quality == "Fast":
            resolution = 8
            max_atoms = 5000
        elif quality == "Good":
            resolution = 12
            max_atoms = 10000
        else:
            resolution = 16
            max_atoms = 20000

        if len(x) > max_atoms:
            sampled_indices = np.random.choice(len(x), max_atoms, replace=False)
            x, y, z = x[sampled_indices], y[sampled_indices], z[sampled_indices]
            elements = elements[sampled_indices]
            chain_ids = chain_ids[sampled_indices]
            b_factors = b_factors[sampled_indices]

        if style == "Ball & Stick":
            self.sample_actor = self.create_ball_stick_display(
                x, y, z, elements, chain_ids, b_factors, size_factor, resolution)
        elif style == "Stick Only":
            self.sample_actor = self.create_stick_display(
                x, y, z, elements, chain_ids, b_factors, size_factor, resolution)
        elif style == "Spheres":
            self.sample_actor = self.create_sphere_display(
                x, y, z, elements, chain_ids, b_factors, size_factor, resolution)
        elif style == "Points":
            self.sample_actor = self.create_point_display(
                x, y, z, elements, chain_ids, b_factors, size_factor)
        elif style == "Wireframe":
            self.sample_actor = self.create_wireframe_display(x, y, z)
        elif style == "Simple Cartoon":
            self.sample_actor = self.create_simple_cartoon_display_safe()
        elif style == "Ribbon":
            self.sample_actor = self.create_ribbon_display(size_factor)
        else:
            self.sample_actor = self.create_sphere_display(
                x, y, z, elements, chain_ids, b_factors, size_factor, resolution)

        if self.sample_actor and hasattr(self.sample_actor, 'GetProperty'):
            self.sample_actor.GetProperty().SetOpacity(opacity)

        if self.sample_actor:
            self.renderer.AddActor(self.sample_actor)

        if style in ["Ball & Stick", "Stick Only"]:
            self.create_bonds_display(
                x, y, z, elements, chain_ids, b_factors, size_factor * 0.3, resolution,
            )

        if hasattr(self, 'combined_transform') and self.combined_transform is not None:
            if self.sample_actor:
                self.sample_actor.SetUserTransform(self.combined_transform)
            if self.bonds_actor:
                self.bonds_actor.SetUserTransform(self.combined_transform)
        try:
            self.update_actor_materials()
        except Exception:
            pass
        try:
            self.renderer.ResetCameraClippingRange()
        except Exception:
            pass
        return self.sample_actor is not None

    def _ensure_vtk_molecule_actors_for_overlay(self):
        """Ensure hidden VTK actors exist for Impose model capture (PyMOL-only safe)."""
        sig = self._vtk_overlay_signature()
        if (
            getattr(self, '_vtk_overlay_signature_cache', None) == sig
            and getattr(self, 'sample_actor', None) is not None
        ):
            if hasattr(self, 'combined_transform') and self.combined_transform is not None:
                if self.sample_actor:
                    self.sample_actor.SetUserTransform(self.combined_transform)
                if self.bonds_actor:
                    self.bonds_actor.SetUserTransform(self.combined_transform)
            return True
        ok = self._build_vtk_molecule_actors()
        if ok:
            self._vtk_overlay_signature_cache = sig
        return ok

    def _collect_model_overlay_vtk_actors(self):
        """Return VTK actors to include in the impose-model capture."""
        actors = []
        if getattr(self, 'sample_actor', None) is not None:
            actors.append(self.sample_actor)
        show_bonds = True
        if hasattr(self, 'show_bonds_check'):
            try:
                show_bonds = bool(self.show_bonds_check.isChecked())
            except Exception:
                pass
        if show_bonds and getattr(self, 'bonds_actor', None) is not None:
            actors.append(self.bonds_actor)
        mrc_actor = getattr(self, 'mrc_actor', None)
        if mrc_actor is not None:
            try:
                if mrc_actor.GetVisibility():
                    actors.append(mrc_actor)
            except Exception:
                actors.append(mrc_actor)
        return actors

    def _copy_renderer_lights(self, src_renderer, dst_renderer):
        """Duplicate scene lights from one VTK renderer to another."""
        if src_renderer is None or dst_renderer is None:
            return
        try:
            lights = src_renderer.GetLights()
            lights.InitTraversal()
            while True:
                light = lights.GetNextItemAsObject()
                if light is None:
                    break
                new_light = vtk.vtkLight()
                new_light.SetLightTypeToSceneLight()
                new_light.SetPosition(light.GetPosition())
                new_light.SetFocalPoint(light.GetFocalPoint())
                new_light.SetColor(light.GetColor())
                new_light.SetIntensity(light.GetIntensity())
                dst_renderer.AddLight(new_light)
        except Exception:
            pass

    def _vtk_image_to_rgb_array(self, vtk_image):
        """Convert vtkWindowToImageFilter output to a top-down RGB uint8 array."""
        from vtkmodules.util import numpy_support

        if vtk_image is None:
            return None
        try:
            dims = vtk_image.GetDimensions()
            width, height = int(dims[0]), int(dims[1])
            if width <= 0 or height <= 0:
                return None
            scalars = vtk_image.GetPointData().GetScalars()
            if scalars is None:
                return None
            flat = numpy_support.vtk_to_numpy(scalars)
            channels = max(1, int(flat.size // max(1, width * height)))
            arr = flat.reshape(height, width, channels)
            if channels >= 3:
                arr = arr[:, :, :3].astype(np.uint8)
            else:
                return None
            return np.ascontiguousarray(np.flipud(arr))
        except Exception:
            return None

    def _rgb_array_to_rgba_with_chroma_key(self, rgb, bg_rgb, tolerance=18.0):
        """Promote RGB to RGBA by making pixels near the capture background transparent."""
        if rgb is None:
            return None
        rgb = np.asarray(rgb, dtype=np.uint8)
        if rgb.ndim != 3 or rgb.shape[2] < 3:
            return None
        bg = np.asarray(bg_rgb[:3], dtype=np.float32)
        diff = np.linalg.norm(rgb[:, :, :3].astype(np.float32) - bg, axis=2)
        rgba = np.zeros((rgb.shape[0], rgb.shape[1], 4), dtype=np.uint8)
        rgba[:, :, :3] = rgb[:, :, :3]
        rgba[:, :, 3] = np.where(diff > float(tolerance), 255, 0).astype(np.uint8)
        return rgba

    def _vtk_image_to_rgba_array(self, vtk_image):
        """Convert vtkWindowToImageFilter output to a top-down RGBA uint8 array."""
        from vtkmodules.util import numpy_support

        if vtk_image is None:
            return None
        try:
            dims = vtk_image.GetDimensions()
            width, height = int(dims[0]), int(dims[1])
            if width <= 0 or height <= 0:
                return None
            scalars = vtk_image.GetPointData().GetScalars()
            if scalars is None:
                return None
            flat = numpy_support.vtk_to_numpy(scalars)
            channels = max(1, int(flat.size // max(1, width * height)))
            arr = flat.reshape(height, width, channels)
            if channels == 3:
                alpha = np.full((height, width, 1), 255, dtype=np.uint8)
                arr = np.concatenate([arr.astype(np.uint8), alpha], axis=2)
            elif channels >= 4:
                arr = arr[:, :, :4].astype(np.uint8)
            else:
                return None
            return np.ascontiguousarray(np.flipud(arr))
        except Exception:
            return None

    def _rgba_array_to_qpixmap(self, rgba):
        """Convert an RGBA uint8 array to a QPixmap."""
        from PyQt5.QtGui import QImage, QPixmap

        if rgba is None:
            return None
        rgba = np.ascontiguousarray(rgba, dtype=np.uint8)
        if rgba.ndim != 3 or rgba.shape[2] < 4:
            return None
        height, width = int(rgba.shape[0]), int(rgba.shape[1])
        if width <= 0 or height <= 0:
            return None
        # Build ARGB32 explicitly (Format_RGBA8888 via sip.voidptr is unreliable on some macOS/PyQt builds).
        argb = np.empty((height, width, 4), dtype=np.uint8)
        argb[:, :, 0] = rgba[:, :, 2]  # B
        argb[:, :, 1] = rgba[:, :, 1]  # G
        argb[:, :, 2] = rgba[:, :, 0]  # R
        argb[:, :, 3] = rgba[:, :, 3]  # A
        argb = np.ascontiguousarray(argb)
        bytes_per_line = int(argb.strides[0])
        try:
            import sip  # type: ignore
        except Exception:
            from PyQt5 import sip  # type: ignore
        ptr = sip.voidptr(int(argb.ctypes.data))
        qimg = QImage(ptr, width, height, bytes_per_line, QImage.Format_ARGB32).copy()
        if qimg.isNull():
            return None
        return QPixmap.fromImage(qimg)

    def _pixmap_opaque_pixel_count(self, pixmap, sample_stride=4):
        """Count non-transparent pixels in a QPixmap (sampled for speed)."""
        from PyQt5.QtGui import QImage

        if pixmap is None or pixmap.isNull():
            return 0
        try:
            img = pixmap.toImage().convertToFormat(QImage.Format_ARGB32)
            if img.isNull():
                return 0
            w, h = img.width(), img.height()
            if w <= 0 or h <= 0:
                return 0
            step = max(1, int(sample_stride))
            count = 0
            for y in range(0, h, step):
                for x in range(0, w, step):
                    if (img.pixel(x, y) >> 24) & 0xFF:
                        count += 1
            return count
        except Exception:
            return 0

    def _pixmap_is_valid_overlay(self, pixmap):
        return pixmap is not None and not pixmap.isNull()

    def _overlay_vtk_capture_enabled(self):
        """VTK impose capture is unreliable on macOS (empty/garbage buffers)."""
        if sys.platform == 'darwin':
            return False
        return True

    def _overlay_min_opaque_pixels(self, render_w, render_h, painted_atoms=0):
        if painted_atoms > 0:
            return max(32, int(painted_atoms * 3))
        area = max(1, int(render_w) * int(render_h))
        return max(400, int(area * 0.00004))

    def _pixmap_is_usable_overlay(self, pixmap, render_w, render_h, painted_atoms=0):
        """Reject VTK noise / single-pixel 'success' buffers."""
        if not self._pixmap_is_valid_overlay(pixmap):
            return False
        needed = self._overlay_min_opaque_pixels(render_w, render_h, painted_atoms)
        count = self._pixmap_opaque_pixel_count(pixmap, sample_stride=1)
        return count >= needed

    def _pixmap_has_visible_pixels(self, pixmap, min_pixels=8):
        """Return True when pixmap has opaque pixels (tolerant for sparse Points style)."""
        if not self._pixmap_is_valid_overlay(pixmap):
            return False
        count = self._pixmap_opaque_pixel_count(pixmap, sample_stride=2)
        if count >= int(min_pixels):
            return True
        # Sparse overlays (Points): do a full scan on smaller images only.
        try:
            w, h = pixmap.width(), pixmap.height()
            if w > 0 and h > 0 and (w * h) <= 6_000_000:
                return self._pixmap_opaque_pixel_count(pixmap, sample_stride=1) >= 1
        except Exception:
            pass
        return False

    def _impose_scan_window_nm(self):
        """Return scan window (nm) and display pixel size matching the Real AFM image."""
        real = getattr(self, 'real_afm_nm', None)
        if real is None:
            return None
        meta = self._get_real_afm_simulation_meta()
        if meta is None:
            return None
        scan_x_nm, scan_y_nm, _nx, _ny = meta
        try:
            disp_h, disp_w = int(real.shape[0]), int(real.shape[1])
        except Exception:
            return None
        if disp_w <= 0 or disp_h <= 0 or scan_x_nm <= 0 or scan_y_nm <= 0:
            return None
        center_x, center_y = self._get_tip_center_xy_nm()
        return {
            'scan_x_nm': float(scan_x_nm),
            'scan_y_nm': float(scan_y_nm),
            'disp_w': int(disp_w),
            'disp_h': int(disp_h),
            'center_x': float(center_x),
            'center_y': float(center_y),
            'x_start': float(center_x) - float(scan_x_nm) / 2.0,
            'y_start': float(center_y) - float(scan_y_nm) / 2.0,
            'nm_per_px_x': float(scan_x_nm) / float(disp_w),
            'nm_per_px_y': float(scan_y_nm) / float(disp_h),
        }

    def _overlay_render_pixel_size(self, win):
        """High-res PNG size: same nm aspect as AFM scan, independent of AFM pixel count."""
        scan_x = float(win['scan_x_nm'])
        scan_y = float(win['scan_y_nm'])
        disp_w = int(win['disp_w'])
        disp_h = int(win['disp_h'])
        long_edge = max(1024, min(2400, max(disp_w, disp_h) * 4))
        if scan_x >= scan_y:
            render_w = long_edge
            render_h = max(64, int(round(long_edge * scan_y / max(scan_x, 1e-9))))
        else:
            render_h = long_edge
            render_w = max(64, int(round(long_edge * scan_x / max(scan_y, 1e-9))))
        return int(render_w), int(render_h)

    def _nm_xy_to_render_px(self, x_nm, y_nm, win, render_w, render_h):
        """Map nm coordinates to high-res render pixels (same nm window as AFM)."""
        nm_per_px_x = float(win['scan_x_nm']) / float(render_w)
        nm_per_px_y = float(win['scan_y_nm']) / float(render_h)
        px = (float(x_nm) - win['x_start']) / nm_per_px_x
        py = (float(render_h) - 1.0) - (float(y_nm) - win['y_start']) / nm_per_px_y
        return px, py

    def _display_structure_opacity(self):
        """Opacity from Display Settings (0–1), separate from Impose overlay blend slider."""
        try:
            if hasattr(self, 'opacity_slider'):
                return min(max(float(self.opacity_slider.value()) / 100.0, 0.0), 1.0)
        except Exception:
            pass
        return 1.0

    def _display_settings_style(self):
        if hasattr(self, 'style_combo'):
            try:
                return str(self.style_combo.currentText())
            except Exception:
                pass
        return "Spheres"

    def _apply_display_opacity_to_pixmap(self, pixmap):
        """Scale pixmap alpha by Display Settings opacity."""
        from PyQt5.QtGui import QImage, QPixmap

        if pixmap is None or pixmap.isNull():
            return pixmap
        alpha_scale = self._display_structure_opacity()
        if alpha_scale >= 0.999:
            return pixmap
        img = pixmap.toImage().convertToFormat(QImage.Format_ARGB32)
        if img.isNull():
            return pixmap
        w, h = img.width(), img.height()
        for y in range(h):
            for x in range(w):
                px = img.pixel(x, y)
                a = (px >> 24) & 0xFF
                if a <= 0:
                    continue
                na = int(round(a * alpha_scale))
                img.setPixel(x, y, (na << 24) | (px & 0x00FFFFFF))
        out = QPixmap.fromImage(img)
        return out if not out.isNull() else pixmap

    def _overlay_atom_limit_for_quality(self):
        quality = self.quality_combo.currentText() if hasattr(self, 'quality_combo') else "Good"
        if quality == "Fast":
            return 15000
        if quality == "High":
            return 60000
        return 40000

    def _overlay_sphere_radius_px(self, style, size_factor, nm_per_px):
        """Approximate on-screen atom radius (px) for QPainter fallback."""
        sf = float(size_factor)
        npp = max(float(nm_per_px), 1e-9)
        if style == "Points":
            return max(2.5, 0.10 * sf / npp)
        if style == "Stick Only":
            return max(1.0, 0.02 * sf / npp)
        if style == "Ball & Stick":
            return max(2.0, 0.10 * sf / npp)
        return max(3.0, 0.15 * sf / npp)

    def _overlay_prefers_vtk_capture(self, style=None):
        """Styles that need VTK capture (QPainter cannot approximate them)."""
        if style is None:
            style = self._display_settings_style()
        # Cartoon / Ribbon are drawn by _render_cartoon_overlay_qpainter.
        return style in ("Ball & Stick", "Stick Only", "Wireframe")

    def _overlay_skip_qpainter_atoms(self, style):
        """QPainter cannot draw stick-only; defer to VTK when possible."""
        return style == "Stick Only"

    def _collect_ca_backbone_segments(self, rotated):
        """CA (or P) backbone polylines per chain in residue order."""
        if self.atoms_data is None or rotated is None:
            return []
        atom_names = np.asarray(self.atoms_data['atom_name'])
        ca_mask = atom_names == 'CA'
        if not np.any(ca_mask):
            ca_mask = atom_names == 'P'
        if not np.any(ca_mask):
            return []
        chain_ids = np.asarray(self.atoms_data['chain_id'])[ca_mask]
        residue_ids = np.asarray(self.atoms_data['residue_id'])[ca_mask]
        elements = np.asarray(self.atoms_data['element'])[ca_mask]
        b_factors = np.asarray(self.atoms_data['b_factor'])[ca_mask]
        x = np.asarray(rotated[ca_mask, 0], dtype=np.float64)
        y = np.asarray(rotated[ca_mask, 1], dtype=np.float64)
        z = np.asarray(rotated[ca_mask, 2], dtype=np.float64)

        segments = []
        for chain in np.unique(chain_ids):
            cm = chain_ids == chain
            order = np.argsort(residue_ids[cm], kind='mergesort')
            seg_x = x[cm][order]
            seg_y = y[cm][order]
            seg_z = z[cm][order]
            if seg_x.size < 2:
                continue
            segments.append({
                'chain': chain,
                'x': seg_x,
                'y': seg_y,
                'z': seg_z,
                'residue_id': residue_ids[cm][order],
                'elements': elements[cm][order],
                'b_factors': b_factors[cm][order],
            })
        return segments

    @staticmethod
    def _catmull_rom_xy(p0, p1, p2, p3, t):
        """Catmull-Rom interpolation on 3D points; returns (x, y, z)."""
        t = float(t)
        p0 = np.asarray(p0, dtype=np.float64)
        p1 = np.asarray(p1, dtype=np.float64)
        p2 = np.asarray(p2, dtype=np.float64)
        p3 = np.asarray(p3, dtype=np.float64)
        pt = (
            0.5 * (
                (2.0 * p1)
                + (-p0 + p2) * t
                + (2.0 * p0 - 5.0 * p1 + 4.0 * p2 - p3) * (t * t)
                + (-p0 + 3.0 * p1 - 3.0 * p2 + p3) * (t * t * t)
            )
        )
        return float(pt[0]), float(pt[1]), float(pt[2])

    def _ribbon_ss_width_nm(self, ss_type, size_factor):
        if ss_type == 'H':
            return 0.6 * size_factor
        if ss_type == 'E':
            return 0.8 * size_factor
        return 0.2 * size_factor

    def _render_cartoon_overlay_qpainter(self, render_w, render_h, win, style):
        """2D CA backbone overlay for Simple Cartoon / Ribbon (macOS-safe, no VTK capture)."""
        from PyQt5.QtGui import QImage, QPainter, QColor, QPen, QPixmap
        from PyQt5.QtCore import Qt, QPointF

        rotated = self.get_rotated_atom_coords()
        segments = self._collect_ca_backbone_segments(rotated)
        if not segments:
            return None

        size_factor = float(self.size_slider.value()) / 100.0 if hasattr(self, 'size_slider') else 1.0
        nm_per_px = float(win['scan_x_nm']) / float(max(render_w, 1))
        cartoon_width_px = max(2.5, 0.30 * size_factor / max(nm_per_px, 1e-9))

        img = QImage(int(render_w), int(render_h), QImage.Format_ARGB32)
        img.fill(0)
        painter = QPainter(img)
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.setBrush(Qt.NoBrush)

        painted = 0
        subdivisions = 6

        for seg in segments:
            xs = seg['x']
            ys = seg['y']
            zs = seg['z']
            chain = seg['chain']
            n = int(xs.size)

            if style == "Ribbon" and n >= 4:
                ss_types = []
                for res_id in seg['residue_id']:
                    key = (chain, res_id)
                    ss_types.append(self.secondary_structure.get(key, 'C'))

                for i in range(n - 1):
                    p0_idx = max(0, i - 1)
                    p1_idx = i
                    p2_idx = i + 1
                    p3_idx = min(n - 1, i + 2)
                    p0 = (xs[p0_idx], ys[p0_idx], zs[p0_idx])
                    p1 = (xs[p1_idx], ys[p1_idx], zs[p1_idx])
                    p2 = (xs[p2_idx], ys[p2_idx], zs[p2_idx])
                    p3 = (xs[p3_idx], ys[p3_idx], zs[p3_idx])
                    color1 = self.get_atom_color(
                        seg['elements'][p1_idx], chain, seg['b_factors'][p1_idx],
                    )
                    color2 = self.get_atom_color(
                        seg['elements'][p2_idx], chain, seg['b_factors'][p2_idx],
                    )
                    ss_type = ss_types[p1_idx]
                    width_px = max(
                        2.0,
                        self._ribbon_ss_width_nm(ss_type, size_factor) / max(nm_per_px, 1e-9),
                    )
                    prev_pt = None
                    for j in range(subdivisions + 1):
                        t = j / float(subdivisions)
                        cx, cy, _cz = self._catmull_rom_xy(p0, p1, p2, p3, t)
                        px, py = self._nm_xy_to_render_px(cx, cy, win, render_w, render_h)
                        u = 1.0 - t
                        color = (
                            color1[0] * u + color2[0] * t,
                            color1[1] * u + color2[1] * t,
                            color1[2] * u + color2[2] * t,
                        )
                        pt = QPointF(px, py)
                        if prev_pt is not None:
                            pen = QPen(QColor(
                                int(color[0] * 255), int(color[1] * 255), int(color[2] * 255), 255,
                            ))
                            pen.setWidthF(width_px)
                            pen.setCapStyle(Qt.RoundCap)
                            pen.setJoinStyle(Qt.RoundJoin)
                            painter.setPen(pen)
                            painter.drawLine(prev_pt, pt)
                            painted += 1
                        prev_pt = pt
            else:
                pen_width = cartoon_width_px
                for i in range(n - 1):
                    color = self.get_atom_color(
                        seg['elements'][i], chain, seg['b_factors'][i],
                    )
                    px0, py0 = self._nm_xy_to_render_px(xs[i], ys[i], win, render_w, render_h)
                    px1, py1 = self._nm_xy_to_render_px(xs[i + 1], ys[i + 1], win, render_w, render_h)
                    pen = QPen(QColor(
                        int(color[0] * 255), int(color[1] * 255), int(color[2] * 255), 255,
                    ))
                    pen.setWidthF(pen_width)
                    pen.setCapStyle(Qt.RoundCap)
                    pen.setJoinStyle(Qt.RoundJoin)
                    painter.setPen(pen)
                    painter.drawLine(QPointF(px0, py0), QPointF(px1, py1))
                    painted += 1

        painter.end()
        if painted == 0:
            self._overlay_last_qpainter_atoms = 0
            return None
        pixmap = QPixmap.fromImage(img)
        if pixmap.isNull():
            self._overlay_last_qpainter_atoms = 0
            return None
        self._overlay_last_qpainter_atoms = int(painted)
        print(f"[INFO] Impose model: QPainter cartoon ({style}) {painted} segments -> {render_w}x{render_h}")
        return pixmap

    def _capture_vtk_model_overlay_qpixmap(self, render_w, render_h, scan_x_nm, scan_y_nm, center_x, center_y):
        """VTK orthographic capture at high resolution; returns QPixmap with transparency."""
        rgba = self._capture_vtk_model_overlay_rgba(
            render_w, render_h, scan_x_nm, scan_y_nm, center_x, center_y,
        )
        if rgba is None or not self._overlay_capture_is_substantial(rgba, render_w, render_h):
            return None
        return self._rgba_array_to_qpixmap(rgba)

    def _render_atoms_overlay_qpainter(self, render_w, render_h, win):
        """High-res QPainter render fallback (nm-scaled; mirrors Display Settings approximately)."""
        from PyQt5.QtGui import QImage, QPainter, QColor, QBrush, QPixmap
        from PyQt5.QtCore import Qt, QRectF

        style = self._display_settings_style()
        if style in ("Simple Cartoon", "Ribbon"):
            return self._render_cartoon_overlay_qpainter(render_w, render_h, win, style)
        if self._overlay_skip_qpainter_atoms(style):
            return None

        rotated = self.get_rotated_atom_coords()
        if rotated is None or len(rotated) == 0:
            return None

        filt = self.get_filtered_atoms()
        if filt[0] is None:
            return None
        mask = np.asarray(filt[6], dtype=bool)
        elements = np.asarray(filt[3])
        chain_ids = np.asarray(filt[4])
        b_factors = np.asarray(filt[5])

        x = np.asarray(rotated[mask, 0], dtype=np.float64)
        y = np.asarray(rotated[mask, 1], dtype=np.float64)
        z = np.asarray(rotated[mask, 2], dtype=np.float64)

        valid = np.isfinite(x) & np.isfinite(y) & np.isfinite(z)
        if not np.any(valid):
            return None

        idxs = np.flatnonzero(valid)
        atom_limit = self._overlay_atom_limit_for_quality()
        if idxs.size > atom_limit:
            idxs = np.random.choice(idxs, atom_limit, replace=False)

        size_factor = float(self.size_slider.value()) / 100.0 if hasattr(self, 'size_slider') else 1.0
        nm_per_px = float(win['scan_x_nm']) / float(render_w)
        radius_px = self._overlay_sphere_radius_px(style, size_factor, nm_per_px)

        img = QImage(int(render_w), int(render_h), QImage.Format_ARGB32)
        img.fill(0)
        painter = QPainter(img)
        painter.setRenderHint(QPainter.Antialiasing, style != "Points")
        painter.setPen(Qt.NoPen)

        order = idxs[np.argsort(z[idxs], kind='mergesort')]
        painted = 0
        for i in order:
            px, py = self._nm_xy_to_render_px(x[i], y[i], win, render_w, render_h)
            if px < -radius_px or py < -radius_px or px > render_w + radius_px or py > render_h + radius_px:
                continue
            color = self.get_atom_color(elements[i], chain_ids[i], b_factors[i])
            painter.setBrush(QBrush(QColor(
                int(color[0] * 255), int(color[1] * 255), int(color[2] * 255), 255,
            )))
            painter.drawEllipse(QRectF(px - radius_px, py - radius_px, 2.0 * radius_px, 2.0 * radius_px))
            painted += 1
        painter.end()

        if painted == 0:
            self._overlay_last_qpainter_atoms = 0
            return None
        pixmap = QPixmap.fromImage(img)
        if pixmap.isNull():
            self._overlay_last_qpainter_atoms = 0
            return None
        self._overlay_last_qpainter_atoms = int(painted)
        print(f"[INFO] Impose model: QPainter ({style}) {painted} atoms -> {render_w}x{render_h} PNG")
        return pixmap

    def _build_model_overlay_png_pixmap(self):
        """Render PDB model to a high-res transparent PNG framed on the AFM scan window (nm)."""
        if self.atoms_data is None:
            print("[WARNING] Impose model: no PDB loaded")
            return None

        win = self._impose_scan_window_nm()
        if win is None:
            print("[WARNING] Impose model: scan window metadata is incomplete")
            return None

        render_w, render_h = self._overlay_render_pixel_size(win)
        center_x = win['center_x']
        center_y = win['center_y']
        style = self._display_settings_style()
        qp_pixmap = self._render_atoms_overlay_qpainter(render_w, render_h, win)
        painted = int(getattr(self, '_overlay_last_qpainter_atoms', 0))
        pixmap = None

        # QPainter is authoritative whenever it painted atoms (stable on macOS).
        if painted > 0 and self._pixmap_is_valid_overlay(qp_pixmap):
            pixmap = qp_pixmap
            print(f"[INFO] Impose model: using QPainter ({style}), {painted} atoms")

        elif (
            self._overlay_vtk_capture_enabled()
            and self._overlay_prefers_vtk_capture(style)
        ):
            self._ensure_vtk_molecule_actors_for_overlay()
            vtk_pixmap = self._capture_vtk_model_overlay_qpixmap(
                render_w, render_h, win['scan_x_nm'], win['scan_y_nm'], center_x, center_y,
            )
            if self._pixmap_is_usable_overlay(vtk_pixmap, render_w, render_h):
                pixmap = vtk_pixmap
                print(f"[INFO] Impose model: VTK ({style}) -> {render_w}x{render_h} PNG")

        if pixmap is None:
            splat_pixmap = self._build_model_overlay_pixmap_splat_at_size(
                render_w, render_h, win, allow_stick_only_fallback=True,
            )
            if splat_pixmap is not None and not splat_pixmap.isNull():
                opaque = self._pixmap_opaque_pixel_count(splat_pixmap, sample_stride=1)
                if opaque >= self._overlay_min_opaque_pixels(render_w, render_h) or opaque >= 32:
                    pixmap = splat_pixmap
                    print(f"[INFO] Impose model: splat fallback -> {render_w}x{render_h} PNG ({opaque} px)")

        if pixmap is None or pixmap.isNull():
            print("[WARNING] Impose model: failed to render model PNG")
            return None

        pixmap = self._apply_display_opacity_to_pixmap(pixmap)
        return self._apply_pose_shift_to_pixmap(pixmap, win)

    def _apply_pose_shift_to_pixmap(self, pixmap, win=None):
        """Apply Estimate Pose residual (dx_px, dy_px in AFM pixels) to overlay PNG."""
        from PyQt5.QtGui import QImage, QPixmap, QPainter

        if pixmap is None or pixmap.isNull():
            return None
        pose = getattr(self, 'pose', None)
        if not isinstance(pose, dict):
            return pixmap
        try:
            dx = float(pose.get('dx_px', 0.0))
            dy = float(pose.get('dy_px', 0.0))
        except Exception:
            return pixmap
        if abs(dx) < 1e-6 and abs(dy) < 1e-6:
            return pixmap

        if isinstance(win, dict):
            disp_w = max(1, int(win.get('disp_w', pixmap.width())))
            disp_h = max(1, int(win.get('disp_h', pixmap.height())))
            dx = dx * (float(pixmap.width()) / float(disp_w))
            dy = dy * (float(pixmap.height()) / float(disp_h))

        img = pixmap.toImage().convertToFormat(QImage.Format_ARGB32)
        w, h = img.width(), img.height()
        shifted = QImage(w, h, QImage.Format_ARGB32)
        shifted.fill(0)
        p = QPainter(shifted)
        # Pixmaps are display-oriented (already flipud'd). Qt +y is down, while
        # pose dy is defined in pre-flip array space, so invert Y here.
        p.drawImage(int(round(dx)), int(round(-dy)), img)
        p.end()
        out = QPixmap.fromImage(shifted)
        if out.isNull():
            return pixmap
        if self._pixmap_has_visible_pixels(out, min_pixels=10):
            return out
        print("[WARNING] Impose model: pose shift removed overlay; keeping unshifted image")
        return pixmap

    def _overlay_opaque_pixel_count(self, rgba):
        try:
            arr = np.asarray(rgba)
            if arr.ndim != 3 or arr.shape[2] < 4:
                return 0
            return int(np.count_nonzero(arr[:, :, 3]))
        except Exception:
            return 0

    def _overlay_capture_is_substantial(self, rgba, disp_w, disp_h, min_fraction=0.0005, min_pixels=200):
        count = self._overlay_opaque_pixel_count(rgba)
        if count <= 0:
            return False
        total = max(1, int(disp_w) * int(disp_h))
        return count >= max(int(min_pixels), int(round(total * float(min_fraction))))

    def _paint_disk_rgba(self, rgba, cx, cy, radius, color_rgba):
        """Paint a filled disk onto an RGBA uint8 image (in-place)."""
        if rgba is None or radius <= 0:
            return
        h, w = int(rgba.shape[0]), int(rgba.shape[1])
        cx_i = int(round(float(cx)))
        cy_i = int(round(float(cy)))
        r = int(max(1, round(float(radius))))
        y0 = max(0, cy_i - r)
        y1 = min(h, cy_i + r + 1)
        x0 = max(0, cx_i - r)
        x1 = min(w, cx_i + r + 1)
        if y0 >= y1 or x0 >= x1:
            return
        yy, xx = np.ogrid[y0:y1, x0:x1]
        disk = ((xx - cx_i) ** 2 + (yy - cy_i) ** 2) <= (r * r)
        patch = rgba[y0:y1, x0:x1]
        patch[disk] = color_rgba

    def _build_model_overlay_pixmap_splat(self):
        """Project rotated PDB atoms onto the Real AFM grid as coloured spheres."""
        real = getattr(self, 'real_afm_nm', None)
        if real is None or self.atoms_data is None:
            return None
        meta = self._get_real_afm_simulation_meta()
        if meta is None:
            return None
        scan_x_nm, scan_y_nm, nx, ny = meta
        try:
            disp_h, disp_w = int(real.shape[0]), int(real.shape[1])
        except Exception:
            return None
        if disp_w <= 0 or disp_h <= 0 or scan_x_nm <= 0 or scan_y_nm <= 0:
            return None

        center_x, center_y = self._get_tip_center_xy_nm()
        x_start = center_x - float(scan_x_nm) / 2.0
        y_start = center_y - float(scan_y_nm) / 2.0

        rotated = self.get_rotated_atom_coords()
        if rotated is None:
            return None
        filt = self.get_filtered_atoms()
        if filt[0] is None:
            return None
        mask = filt[6]
        elements = filt[3]
        chain_ids = filt[4]
        b_factors = filt[5]

        x = np.asarray(rotated[mask, 0], dtype=np.float64)
        y = np.asarray(rotated[mask, 1], dtype=np.float64)
        z = np.asarray(rotated[mask, 2], dtype=np.float64)
        valid = np.isfinite(x) & np.isfinite(y) & np.isfinite(z)
        if not np.any(valid):
            return None
        x, y, z = x[valid], y[valid], z[valid]
        elements = elements[valid]
        chain_ids = chain_ids[valid]
        b_factors = b_factors[valid]
        if x.size > 20000:
            pick = np.random.choice(x.size, 20000, replace=False)
            x, y, z = x[pick], y[pick], z[pick]
            elements = elements[pick]
            chain_ids = chain_ids[pick]
            b_factors = b_factors[pick]

        size_factor = float(self.size_slider.value()) / 100.0 if hasattr(self, 'size_slider') else 1.0
        nm_per_px_x = float(scan_x_nm) / float(max(disp_w, 1))
        sphere_nm = max(0.05, 0.15 * size_factor)
        radius_px = max(2, int(round(sphere_nm / max(nm_per_px_x, 1e-6))))

        rgba = np.zeros((disp_h, disp_w, 4), dtype=np.uint8)
        order = np.argsort(z, kind='mergesort')
        for idx in order:
            px = (float(x[idx]) - x_start) / float(scan_x_nm) * float(disp_w)
            py = (float(y[idx]) - y_start) / float(scan_y_nm) * float(disp_h)
            if px < -radius_px or py < -radius_px or px > disp_w + radius_px or py > disp_h + radius_px:
                continue
            color = self.get_atom_color(elements[idx], chain_ids[idx], b_factors[idx])
            color_rgba = np.array(
                [int(color[0] * 255), int(color[1] * 255), int(color[2] * 255), 255],
                dtype=np.uint8,
            )
            self._paint_disk_rgba(rgba, px, py, radius_px, color_rgba)

        if not np.any(rgba[:, :, 3]):
            print("[WARNING] Impose model: atom splat produced an empty overlay")
            return None

        rgba_display = np.ascontiguousarray(np.flipud(rgba))
        return self._finalize_model_overlay_rgba(rgba_display, struct_opacity=1.0)

    def _build_model_overlay_pixmap_splat_at_size(self, render_w, render_h, win, allow_stick_only_fallback=False):
        """High-res splat fallback: project atoms onto a nm-scaled render grid."""
        if self.atoms_data is None or win is None:
            return None
        render_w = int(render_w)
        render_h = int(render_h)
        if render_w <= 0 or render_h <= 0:
            return None

        rotated = self.get_rotated_atom_coords()
        if rotated is None:
            return None
        filt = self.get_filtered_atoms()
        if filt[0] is None:
            return None
        mask = np.asarray(filt[6], dtype=bool)
        elements = np.asarray(filt[3])
        chain_ids = np.asarray(filt[4])
        b_factors = np.asarray(filt[5])

        x = np.asarray(rotated[mask, 0], dtype=np.float64)
        y = np.asarray(rotated[mask, 1], dtype=np.float64)
        z = np.asarray(rotated[mask, 2], dtype=np.float64)
        valid = np.isfinite(x) & np.isfinite(y) & np.isfinite(z)
        if not np.any(valid):
            return None
        x, y, z = x[valid], y[valid], z[valid]
        elements = elements[valid]
        chain_ids = chain_ids[valid]
        b_factors = b_factors[valid]
        if x.size > self._overlay_atom_limit_for_quality():
            pick = np.random.choice(x.size, self._overlay_atom_limit_for_quality(), replace=False)
            x, y, z = x[pick], y[pick], z[pick]
            elements = elements[pick]
            chain_ids = chain_ids[pick]
            b_factors = b_factors[pick]

        style = self._display_settings_style()
        if self._overlay_skip_qpainter_atoms(style) and not allow_stick_only_fallback:
            return None

        size_factor = float(self.size_slider.value()) / 100.0 if hasattr(self, 'size_slider') else 1.0
        nm_per_px = float(win['scan_x_nm']) / float(render_w)
        radius_px = self._overlay_sphere_radius_px(style, size_factor, nm_per_px)

        rgba = np.zeros((render_h, render_w, 4), dtype=np.uint8)
        order = np.argsort(z, kind='mergesort')
        for idx in order:
            px, py = self._nm_xy_to_render_px(x[idx], y[idx], win, render_w, render_h)
            if px < -radius_px or py < -radius_px or px > render_w + radius_px or py > render_h + radius_px:
                continue
            color = self.get_atom_color(elements[idx], chain_ids[idx], b_factors[idx])
            color_rgba = np.array(
                [int(color[0] * 255), int(color[1] * 255), int(color[2] * 255), 255],
                dtype=np.uint8,
            )
            self._paint_disk_rgba(rgba, px, py, radius_px, color_rgba)

        if not np.any(rgba[:, :, 3]):
            return None
        return self._rgba_array_to_qpixmap(rgba)

    def _finalize_model_overlay_rgba(self, rgba, struct_opacity=1.0):
        """Apply pose shift, optional alpha scaling, and convert to QPixmap."""
        if rgba is None:
            return None
        rgba = np.asarray(rgba, dtype=np.uint8)
        if rgba.ndim != 3 or rgba.shape[2] < 4 or not np.any(rgba[:, :, 3]):
            return None

        alpha_scale = min(max(float(struct_opacity), 0.0), 1.0)
        if alpha_scale < 1.0:
            rgba = rgba.copy()
            rgba[:, :, 3] = (rgba[:, :, 3].astype(np.float32) * alpha_scale).astype(np.uint8)

        pose = getattr(self, 'pose', None)
        if isinstance(pose, dict):
            try:
                dx = float(pose.get('dx_px', 0.0))
                dy = float(pose.get('dy_px', 0.0))
            except Exception:
                dx = dy = 0.0
            if abs(dx) > 1e-6 or abs(dy) > 1e-6:
                before = int(np.count_nonzero(rgba[:, :, 3]))
                shifted = rgba.copy()
                # rgba is already flipud'd for display. Negate dy so the residual
                # matches Difference-panel shifting performed before flipud.
                for ch in range(4):
                    shifted[:, :, ch] = scipy.ndimage.shift(
                        shifted[:, :, ch],
                        shift=(-dy, dx),
                        order=0,
                        mode='constant',
                        cval=0.0,
                    )
                after = int(np.count_nonzero(shifted[:, :, 3]))
                if after > 0 or before == 0:
                    rgba = shifted
                else:
                    print("[WARNING] Impose model: pose shift removed overlay; keeping unshifted image")

        return self._rgba_array_to_qpixmap(rgba)

    def _capture_vtk_model_overlay_rgba(self, disp_w, disp_h, scan_x_nm, scan_y_nm, center_x, center_y):
        """Capture the current VTK molecule render framed on the AFM scan window.

        Uses the existing ``vtk_widget`` render window (same path as Save 3D View) because
        macOS off-screen ``vtkRenderWindow`` instances often return empty buffers.
        """
        if disp_w <= 0 or disp_h <= 0 or scan_x_nm <= 0 or scan_y_nm <= 0:
            return None
        if not self._ensure_vtk_molecule_actors_for_overlay():
            print("[WARNING] Impose model: failed to build VTK overlay actors")
            return None

        vtk_widget = getattr(self, 'vtk_widget', None)
        if vtk_widget is None or not getattr(self, 'renderer', None):
            print("[WARNING] Impose model: VTK widget/renderer unavailable")
            return None
        rw = vtk_widget.GetRenderWindow()
        if rw is None:
            print("[WARNING] Impose model: VTK render window unavailable")
            return None

        actors = self._collect_model_overlay_vtk_actors()
        if not actors:
            print("[WARNING] Impose model: no VTK actors to capture")
            return None

        cam = self.renderer.GetActiveCamera()
        if cam is None:
            return None

        saved_size = list(rw.GetSize())
        if saved_size[0] < 16 or saved_size[1] < 16:
            try:
                saved_size = [
                    max(16, int(vtk_widget.width())),
                    max(16, int(vtk_widget.height())),
                ]
            except Exception:
                saved_size = [max(16, int(disp_w)), max(16, int(disp_h))]
        capture_bg = (1.0, 0.0, 1.0)
        bg_rgb = (255, 0, 255)
        saved_bg = self.renderer.GetBackground()
        try:
            saved_bg_alpha = float(self.renderer.GetBackgroundAlpha())
        except Exception:
            saved_bg_alpha = 1.0
        saved_cam = {
            'position': cam.GetPosition(),
            'focal': cam.GetFocalPoint(),
            'view_up': cam.GetViewUp(),
            'parallel': bool(cam.GetParallelProjection()),
            'parallel_scale': float(cam.GetParallelScale()),
            'view_angle': float(cam.GetViewAngle()),
            'clipping_range': cam.GetClippingRange(),
        }

        tip_actor = getattr(self, 'tip_actor', None)
        tip_was_visible = None
        if tip_actor is not None:
            try:
                tip_was_visible = bool(tip_actor.GetVisibility())
                tip_actor.SetVisibility(0)
            except Exception:
                tip_was_visible = None

        orient_widget = getattr(self, 'orientation_widget', None)
        orient_was_enabled = None
        if orient_widget is not None:
            try:
                orient_was_enabled = bool(orient_widget.GetEnabled())
                orient_widget.SetEnabled(0)
            except Exception:
                orient_was_enabled = None

        vtk_container = getattr(self, 'vtk_view_container', None)
        container_was_visible = bool(vtk_container.isVisible()) if vtk_container is not None else True
        if vtk_container is not None and not container_was_visible:
            try:
                vtk_container.setVisible(True)
                QApplication.processEvents()
            except Exception:
                container_was_visible = True

        bounds = self._get_structure_bounds_for_camera_fit()
        if bounds is not None:
            z_center = 0.5 * (bounds[4] + bounds[5])
            z_extent = max(bounds[5] - bounds[4], 1.0)
        else:
            z_center = 0.0
            z_extent = 100.0

        actor_opacities = []
        for actor in actors:
            try:
                prop = actor.GetProperty()
                actor_opacities.append(float(prop.GetOpacity()))
                prop.SetOpacity(1.0)
            except Exception:
                actor_opacities.append(None)

        try:
            self.renderer.SetBackground(capture_bg[0], capture_bg[1], capture_bg[2])
            try:
                self.renderer.SetBackgroundAlpha(1.0)
            except Exception:
                pass

            cam.SetParallelProjection(True)
            cam.SetFocalPoint(float(center_x), float(center_y), float(z_center))
            cam.SetPosition(
                float(center_x), float(center_y), float(z_center + max(200.0, z_extent * 3.0)),
            )
            cam.SetViewUp(0.0, 1.0, 0.0)
            aspect_img = float(disp_w) / float(disp_h)
            ps_y = float(scan_y_nm) / 2.0
            ps_x = float(scan_x_nm) / (2.0 * aspect_img)
            cam.SetParallelScale(max(ps_y, ps_x))
            self.renderer.ResetCameraClippingRange()

            rw.SetSize(int(disp_w), int(disp_h))
            try:
                vtk_widget.setVisible(True)
                QApplication.processEvents()
            except Exception:
                pass
            rw.Render()

            rgba = None
            for buffer_type, label in (("rgb", "RGB"), ("rgba", "RGBA")):
                try:
                    w2i = vtk.vtkWindowToImageFilter()
                    w2i.SetInput(rw)
                    if label == "RGBA":
                        w2i.SetInputBufferTypeToRGBA()
                    else:
                        w2i.SetInputBufferTypeToRGB()
                    w2i.ReadFrontBufferOff()
                    w2i.SetScale(1)
                    w2i.Update()
                    if label == "RGBA":
                        rgba = self._vtk_image_to_rgba_array(w2i.GetOutput())
                    else:
                        rgb = self._vtk_image_to_rgb_array(w2i.GetOutput())
                        rgba = self._rgb_array_to_rgba_with_chroma_key(rgb, bg_rgb)
                    if rgba is not None and np.any(rgba[:, :, 3] > 0):
                        break
                    rgba = None
                except Exception as inner_e:
                    print(f"[WARNING] Impose model: VTK {label} capture attempt failed: {inner_e}")
                    rgba = None

            if rgba is None or not np.any(rgba[:, :, 3]):
                try:
                    grabbed = vtk_widget.grab()
                    if grabbed is not None and not grabbed.isNull():
                        from PyQt5.QtGui import QImage
                        qimg = grabbed.toImage().convertToFormat(QImage.Format_RGBA8888)
                        if not qimg.isNull():
                            qw, qh = qimg.width(), qimg.height()
                            if qw > 0 and qh > 0:
                                ptr = qimg.bits()
                                ptr.setsize(qh * qw * 4)
                                arr = np.frombuffer(ptr, dtype=np.uint8).reshape(qh, qw, 4).copy()
                                rgb = arr[:, :, :3]
                                keyed = self._rgb_array_to_rgba_with_chroma_key(rgb, bg_rgb, tolerance=40.0)
                                if keyed is not None and np.any(keyed[:, :, 3] > 0):
                                    rgba = keyed
                except Exception as grab_e:
                    print(f"[WARNING] Impose model: QWidget.grab fallback failed: {grab_e}")

            if rgba is None or not np.any(rgba[:, :, 3]):
                print("[WARNING] Impose model: VTK capture returned empty buffer")
            return rgba
        except Exception as e:
            print(f"[WARNING] Impose model: VTK capture failed: {e}")
            return None
        finally:
            for actor, saved_opacity in zip(actors, actor_opacities):
                if saved_opacity is not None:
                    try:
                        actor.GetProperty().SetOpacity(saved_opacity)
                    except Exception:
                        pass
            try:
                self.renderer.SetBackground(saved_bg[0], saved_bg[1], saved_bg[2])
                try:
                    self.renderer.SetBackgroundAlpha(saved_bg_alpha)
                except Exception:
                    pass
                cam.SetParallelProjection(saved_cam['parallel'])
                cam.SetPosition(saved_cam['position'])
                cam.SetFocalPoint(saved_cam['focal'])
                cam.SetViewUp(saved_cam['view_up'])
                cam.SetParallelScale(saved_cam['parallel_scale'])
                cam.SetViewAngle(saved_cam['view_angle'])
                cam.SetClippingRange(saved_cam['clipping_range'][0], saved_cam['clipping_range'][1])
                if tip_actor is not None and tip_was_visible is not None:
                    tip_actor.SetVisibility(1 if tip_was_visible else 0)
                if orient_widget is not None and orient_was_enabled is not None:
                    orient_widget.SetEnabled(1 if orient_was_enabled else 0)
                if vtk_container is not None and not container_was_visible:
                    try:
                        vtk_container.setVisible(False)
                    except Exception:
                        pass
                rw.SetSize(int(saved_size[0]), int(saved_size[1]))
                rw.Render()
            except Exception:
                pass

    def _capture_pymol_model_overlay_rgba(self, disp_w, disp_h, scan_x_nm, scan_y_nm, center_x, center_y):
        """PyMOL off-screen render framed on the AFM scan window (PyMOL-only mode)."""
        if not self._is_pymol_active() or self.pymol_cmd is None:
            return None
        if disp_w <= 0 or disp_h <= 0 or scan_x_nm <= 0 or scan_y_nm <= 0:
            return None

        frame_obj = "_pynud_scan_overlay_frame"
        saved = {}
        try:
            saved['view'] = list(self.pymol_cmd.get_view())
        except Exception:
            saved['view'] = None
        for key in ("opaque_background", "ray_opaque_background"):
            try:
                saved[key] = self.pymol_cmd.get(key)
            except Exception:
                pass

        try:
            cx_a = float(center_x) * 10.0
            cy_a = float(center_y) * 10.0
            hx_a = float(scan_x_nm) * 5.0
            hy_a = float(scan_y_nm) * 5.0
            z_a = 0.0
            bounds = self._get_structure_bounds_for_camera_fit()
            if bounds is not None:
                z_a = 0.5 * (bounds[4] + bounds[5]) * 10.0

            try:
                self.pymol_cmd.delete(frame_obj)
            except Exception:
                pass
            corner_names = []
            for i, (px, py) in enumerate((
                (cx_a - hx_a, cy_a - hy_a),
                (cx_a + hx_a, cy_a - hy_a),
                (cx_a - hx_a, cy_a + hy_a),
                (cx_a + hx_a, cy_a + hy_a),
            )):
                name = f"{frame_obj}_{i}"
                corner_names.append(name)
                self.pymol_cmd.pseudoatom(name, pos=[px, py, z_a], color="white", vdw=0.01)
            self.pymol_cmd.group(frame_obj, " ".join(corner_names))

            self._pymol_set_standard_view('xy')
            self.pymol_cmd.zoom(frame_obj, buffer=0)
            self.pymol_cmd.viewport(int(disp_w), int(disp_h))
            try:
                self.pymol_cmd.set("opaque_background", 0)
                self.pymol_cmd.set("ray_opaque_background", 0)
            except Exception:
                pass

            tmp_path = os.path.join(tempfile.gettempdir(), "pynud_impose_overlay.png")
            self.pymol_cmd.png(tmp_path, int(disp_w), int(disp_h), dpi=120, ray=0, quiet=1)
            from PyQt5.QtGui import QImage
            qimg = QImage(tmp_path)
            if qimg.isNull():
                return None
            qimg = qimg.convertToFormat(QImage.Format_RGBA8888)
            width, height = qimg.width(), qimg.height()
            if width <= 0 or height <= 0:
                return None
            ptr = qimg.bits()
            ptr.setsize(height * width * 4)
            return np.frombuffer(ptr, dtype=np.uint8).reshape(height, width, 4).copy()
        except Exception:
            return None
        finally:
            try:
                self.pymol_cmd.delete(frame_obj)
            except Exception:
                pass
            if saved.get('view') is not None:
                try:
                    self.pymol_cmd.set_view(saved['view'])
                except Exception:
                    pass
            for key in ("opaque_background", "ray_opaque_background"):
                if key in saved:
                    try:
                        self.pymol_cmd.set(key, saved[key])
                    except Exception:
                        pass

    def _build_model_overlay_pixmap(self):
        """Build a transparent PNG overlay aligned 1:1 with the Real AFM image pixels."""
        return self._build_model_overlay_png_pixmap()

    def _build_model_overlay_pixmap_binning(self):
        """Fallback: rasterize max-Z surface atoms onto the Real AFM grid."""
        real = getattr(self, 'real_afm_nm', None)
        if real is None or self.atoms_data is None:
            return None
        meta = self._get_real_afm_simulation_meta()
        if meta is None:
            return None
        scan_x_nm, scan_y_nm, nx, ny = meta
        nx = int(nx)
        ny = int(ny)
        try:
            disp_h, disp_w = int(real.shape[0]), int(real.shape[1])
        except Exception:
            return None
        if disp_w <= 0 or disp_h <= 0 or nx <= 0 or ny <= 0:
            return None

        rotated = self.get_rotated_atom_coords()
        if rotated is None:
            return None
        filt = self.get_filtered_atoms()
        if filt[0] is None:
            return None
        mask = filt[6]
        elements = filt[3]
        chain_ids = filt[4]
        b_factors = filt[5]

        x = np.asarray(rotated[mask, 0], dtype=np.float64)
        y = np.asarray(rotated[mask, 1], dtype=np.float64)
        z = np.asarray(rotated[mask, 2], dtype=np.float64)

        style = self.style_combo.currentText() if hasattr(self, 'style_combo') else "Spheres"

        if style in ("Simple Cartoon", "Ribbon"):
            atom_names = self.atoms_data.get('atom_name', None)
            if atom_names is not None:
                ca_mask = np.array([str(n).strip().upper() == 'CA' for n in atom_names[mask]], dtype=bool)
                if np.any(ca_mask):
                    x, y, z = x[ca_mask], y[ca_mask], z[ca_mask]
                    elements = elements[ca_mask]
                    chain_ids = chain_ids[ca_mask]
                    b_factors = b_factors[ca_mask]

        center_x, center_y = self._get_tip_center_xy_nm()
        pixel_x = scan_x_nm / float(nx)
        pixel_y = scan_y_nm / float(ny)
        if pixel_x <= 0 or pixel_y <= 0:
            return None
        x_start = center_x - scan_x_nm / 2.0
        y_start = center_y - scan_y_nm / 2.0

        # Identical binning to AFMSimulationWorker.create_atom_center_surface.
        ix_sim = np.floor((x - x_start) / pixel_x).astype(np.int32)
        iy_sim = np.floor((y - y_start) / pixel_y).astype(np.int32)
        in_sim = (
            np.isfinite(z)
            & (ix_sim >= 0) & (ix_sim < nx)
            & (iy_sim >= 0) & (iy_sim < ny)
        )
        if not np.any(in_sim):
            print("[WARNING] Impose model: no atoms inside the AFM scan window")
            return None

        ix_sim = ix_sim[in_sim]
        iy_sim = iy_sim[in_sim]
        z = z[in_sim]
        elements = elements[in_sim]
        chain_ids = chain_ids[in_sim]
        b_factors = b_factors[in_sim]

        # Top atom per simulation pixel (max Z).
        order = np.lexsort((z, ix_sim, iy_sim))
        ix_s = ix_sim[order]
        iy_s = iy_sim[order]
        at_end = np.concatenate([
            (ix_s[1:] != ix_s[:-1]) | (iy_s[1:] != iy_s[:-1]),
            [True],
        ])
        surface_idx = order[at_end]
        if surface_idx.size == 0:
            return None

        alpha_u8 = 255
        rgba = np.zeros((disp_h, disp_w, 4), dtype=np.uint8)

        # Paint each simulation cell onto the display grid (nearest-neighbour upscale).
        for k in surface_idx:
            si = int(ix_sim[k])
            sj = int(iy_sim[k])
            color = self.get_atom_color(elements[k], chain_ids[k], b_factors[k])
            r = int(color[0] * 255)
            g = int(color[1] * 255)
            b = int(color[2] * 255)
            x0 = (si * disp_w) // nx
            x1 = max(x0 + 1, ((si + 1) * disp_w) // nx)
            y0 = (sj * disp_h) // ny
            y1 = max(y0 + 1, ((sj + 1) * disp_h) // ny)
            rgba[y0:y1, x0:x1, 0] = r
            rgba[y0:y1, x0:x1, 1] = g
            rgba[y0:y1, x0:x1, 2] = b
            rgba[y0:y1, x0:x1, 3] = alpha_u8

        if not np.any(rgba[:, :, 3]):
            return None

        rgba_display = np.ascontiguousarray(np.flipud(rgba))
        return self._finalize_model_overlay_rgba(rgba_display, struct_opacity=1.0)

    def _is_impose_model_active(self):
        """True when Impose model is enabled on the Real AFM window."""
        check = getattr(self, 'impose_model_check', None)
        if check is not None:
            try:
                return bool(check.isChecked())
            except Exception:
                pass
        return bool(getattr(self, 'impose_model_enabled', False))

    def _wire_display_settings_to_impose_overlay(self):
        """Keep the Real AFM impose overlay in sync with Display Settings."""
        handler = self._on_display_settings_changed_for_overlay
        widgets = (
            getattr(self, 'style_combo', None),
            getattr(self, 'color_combo', None),
            getattr(self, 'atom_combo', None),
            getattr(self, 'quality_combo', None),
            getattr(self, 'size_slider', None),
            getattr(self, 'opacity_slider', None),
        )
        for widget in widgets:
            if widget is None:
                continue
            try:
                if hasattr(widget, 'currentTextChanged'):
                    widget.currentTextChanged.connect(handler)
                elif hasattr(widget, 'valueChanged'):
                    widget.valueChanged.connect(handler)
            except Exception:
                pass
        for slider in (getattr(self, 'size_slider', None), getattr(self, 'opacity_slider', None)):
            if slider is None:
                continue
            try:
                slider.sliderReleased.connect(
                    lambda: self._queue_impose_overlay_refresh(0),
                )
            except Exception:
                pass

    def _on_display_settings_changed_for_overlay(self, *_args):
        """Debounced overlay refresh after Display Settings change (QPainter only on macOS)."""
        self._queue_impose_overlay_refresh(150)

    def _queue_impose_overlay_refresh(self, delay_ms=80):
        """Schedule an impose-overlay rebuild (debounced for sliders)."""
        if not self._is_impose_model_active():
            return
        if getattr(self, '_pose_estimation_running', False):
            return
        timer = getattr(self, '_impose_overlay_refresh_timer', None)
        if timer is None:
            timer = QTimer(self)
            timer.setSingleShot(True)
            timer.timeout.connect(lambda: self._update_model_overlay(force=True))
            self._impose_overlay_refresh_timer = timer
        try:
            timer.stop()
            timer.start(max(0, int(delay_ms)))
        except Exception:
            self._update_model_overlay(force=True)

    def _schedule_model_overlay_update(self, delay_ms=120):
        """Backward-compatible alias."""
        self._queue_impose_overlay_refresh(delay_ms)

    def _update_model_overlay(self, force=False):
        """Refresh the imposed-model overlay on the Real AFM view based on current state."""
        if not force and getattr(self, '_pose_estimation_running', False):
            return
        if self.real_afm_nm is not None:
            try:
                self._ensure_real_afm_window(show=False)
            except Exception:
                pass
        view = self._get_real_afm_view()
        if view is None:
            return
        enabled = self._is_impose_model_active()
        self.impose_model_enabled = enabled
        if not enabled:
            try:
                view.setModelOverlayVisible(False)
            except Exception:
                pass
            return
        try:
            pixmap = self._build_model_overlay_pixmap()
        except Exception as e:
            print(f"[WARNING] Model overlay computation failed: {e}")
            pixmap = None
        if pixmap is None:
            view.setModelOverlayVisible(False)
            print("[WARNING] Impose model: overlay pixmap is empty (check PDB, scan size, tip position)")
            return
        view.setModelOverlayPixmap(pixmap)
        view.setModelOverlayOpacity(float(getattr(self, 'impose_model_opacity', 0.6)))
        view.setModelOverlayVisible(True)
        self.real_afm_window_view = view
        try:
            if hasattr(view, 'parentWidget') and view.parentWidget() is not None:
                view.parentWidget().update()
            view.update()
            view.repaint()
        except Exception:
            pass

    def _compute_difference_map(self):
        """Compute the Real - Sim difference map (nm) plus RMSD/ZNCC metrics.

        Both maps are mean-offset removed before subtraction. If a pose residual
        (dx_px, dy_px) is available, the simulated image is shifted to match the
        Real AFM features before differencing.

        Returns (diff_map, rmsd_nm, zncc) or (None, None, None).
        """
        real = getattr(self, 'real_afm_nm', None)
        sim = getattr(self, 'sim_aligned_nm', None)
        if real is None or sim is None:
            return None, None, None

        real = np.asarray(real, dtype=np.float64)
        sim = np.asarray(sim, dtype=np.float64)
        if real.ndim != 2 or sim.ndim != 2:
            return None, None, None

        # Sentinel / non-finite handling.
        real_valid = np.isfinite(real) & (real > -1e8)
        sim_valid = np.isfinite(sim) & (sim > -1e8)
        if np.count_nonzero(real_valid) < 4 or np.count_nonzero(sim_valid) < 4:
            return None, None, None

        real_f = np.where(real_valid, real, 0.0)
        sim_f = np.where(sim_valid, sim, 0.0)
        sim_mask = sim_valid.astype(np.float64)

        # Resample simulated map onto the Real AFM grid if needed.
        if sim_f.shape != real_f.shape:
            zoom = (real_f.shape[0] / sim_f.shape[0], real_f.shape[1] / sim_f.shape[1])
            try:
                sim_f = scipy.ndimage.zoom(sim_f, zoom, order=1)
                sim_mask = scipy.ndimage.zoom(sim_mask, zoom, order=1)
            except Exception:
                return None, None, None

        # Apply stored pose residual translation to align sim onto real features.
        pose = getattr(self, 'pose', None)
        if isinstance(pose, dict):
            try:
                dx = float(pose.get('dx_px', 0.0))
                dy = float(pose.get('dy_px', 0.0))
            except Exception:
                dx = dy = 0.0
            if abs(dx) > 1e-6 or abs(dy) > 1e-6:
                try:
                    sim_f = scipy.ndimage.shift(sim_f, shift=(dy, dx), order=1, mode='nearest')
                    sim_mask = scipy.ndimage.shift(
                        sim_mask,
                        shift=(dy, dx),
                        order=1,
                        mode='constant',
                        cval=0.0,
                    )
                except Exception:
                    pass

        sim_valid_r = sim_mask > 0.5
        mask = real_valid & sim_valid_r
        if np.count_nonzero(mask) < 4:
            return None, None, None

        real_mean = float(np.mean(real_f[mask]))
        sim_mean = float(np.mean(sim_f[mask]))
        real0 = real_f - real_mean
        sim0 = sim_f - sim_mean

        diff = real0 - sim0
        diff = np.where(mask, diff, np.nan)

        # RMSD / ZNCC: same definition as Estimate Pose (structure map, not noise).
        raw_sim = None
        if isinstance(getattr(self, 'raw_simulation_results', None), dict):
            raw_sim = self.raw_simulation_results.get("XY_Frame")
        meta = self._get_real_afm_simulation_meta()
        sim_for_metrics = sim
        if raw_sim is not None and meta is not None:
            try:
                sim_for_metrics = self._sim_map_for_pose_scoring(raw_sim, *meta)
            except Exception:
                sim_for_metrics = sim
        pose = getattr(self, 'pose', None)
        dx = dy = None
        if isinstance(pose, dict):
            dx = pose.get('dx_px')
            dy = pose.get('dy_px')
        metrics = self._compute_comparison_metrics(real, sim_for_metrics, dx=dx, dy=dy)
        rmsd = metrics.get('rmsd')
        zncc = metrics.get('zncc')
        if rmsd is None:
            d = diff[mask]
            rmsd = float(np.sqrt(np.mean(d * d)))
        if zncc is None:
            real_for_zncc = np.where(mask, real0, np.nan)
            sim_for_zncc = np.where(mask, sim0, np.nan)
            try:
                zncc = float(self.score_zncc(real_for_zncc, sim_for_zncc))
            except Exception:
                zncc = -1e9

        return diff, rmsd, zncc

    def display_diff_image(self, diff_map, target_panel):
        """Display a signed difference map with a diverging colormap centered at 0."""
        import matplotlib.cm as cm
        from PyQt5.QtGui import QImage, QPixmap
        if target_panel is None or diff_map is None:
            return

        finite = np.isfinite(diff_map)
        h, w = diff_map.shape[:2]
        if np.count_nonzero(finite) < 2:
            image_data = np.full((h, w, 3), 180, dtype=np.uint8)
        else:
            vals = np.abs(diff_map[finite])
            vmax = float(np.percentile(vals, 99.0))
            if not np.isfinite(vmax) or vmax <= 1e-12:
                vmax = float(np.max(vals)) if vals.size else 1.0
            if vmax <= 1e-12:
                vmax = 1.0
            norm = np.clip((np.nan_to_num(diff_map, nan=0.0) + vmax) / (2.0 * vmax), 0.0, 1.0)
            image_data = (cm.seismic(norm)[:, :, :3] * 255).astype(np.uint8)
            # Neutral gray for invalid pixels.
            image_data[~finite] = (180, 180, 180)

        image_data_flipped = np.ascontiguousarray(np.flipud(image_data))
        height, width, _channel = image_data_flipped.shape
        bytes_per_line = int(image_data_flipped.strides[0])
        try:
            import sip  # type: ignore
        except Exception:
            from PyQt5 import sip  # type: ignore
        ptr = sip.voidptr(int(image_data_flipped.ctypes.data))
        qimg = QImage(ptr, width, height, bytes_per_line, QImage.Format_RGB888).copy()

        container = target_panel.findChild(QWidget, "afm_image_container")
        if container is None:
            container = target_panel
        view = container.findChild(_AspectPixmapView, "afm_image_view")
        placeholder = container.findChild(QLabel, "afm_placeholder")
        layout = container.layout()
        if view is None:
            view = _AspectPixmapView(container)
            view.setObjectName("afm_image_view")
            if layout is None:
                layout = QStackedLayout(container)
                layout.setContentsMargins(0, 0, 0, 0)
            try:
                layout.addWidget(view)
            except Exception:
                pass

        pixmap = QPixmap.fromImage(qimg)
        view.setSourcePixmap(pixmap)

        aspect = None
        try:
            if getattr(self, "real_meta", None):
                sx = float(self.real_meta.get("scan_x_nm", 0.0))
                sy = float(self.real_meta.get("scan_y_nm", 0.0))
                if sx > 0 and sy > 0:
                    aspect = sx / sy
        except Exception:
            aspect = None
        view.setDisplayAspectRatio(aspect)

        if layout is not None and hasattr(layout, "setCurrentWidget"):
            try:
                layout.setCurrentWidget(view)
            except Exception:
                pass
        elif placeholder is not None:
            try:
                placeholder.setVisible(False)
                view.setVisible(True)
            except Exception:
                pass

    def _update_difference_panel(self):
        """Recompute and refresh the Difference panel and its RMSD/ZNCC label."""
        diff_frame = getattr(self, 'real_afm_window_diff_frame', None)
        if diff_frame is None:
            return
        info_label = getattr(self, 'real_afm_diff_info_label', None)
        try:
            diff_map, rmsd, zncc = self._compute_difference_map()
        except Exception as e:
            print(f"[WARNING] Difference computation failed: {e}")
            diff_map = None
            rmsd = zncc = None
        if diff_map is None:
            self._clear_afm_panel(diff_frame)
            if info_label is not None:
                try:
                    if getattr(self, 'sim_aligned_nm', None) is None:
                        info_label.setText("RMSD: -    ZNCC: -   (run Get Simulated image)")
                    else:
                        info_label.setText("RMSD: -    ZNCC: -")
                except Exception:
                    pass
            return
        self.display_diff_image(diff_map, diff_frame)
        if info_label is not None:
            try:
                zncc_text = f"{zncc:.3f}" if (zncc is not None and zncc > -1e8) else "-"
                info_label.setText(f"RMSD: {rmsd:.3f} nm    ZNCC: {zncc_text}")
            except Exception:
                pass

    def _clear_afm_panel(self, target_panel):
        """Show placeholder and clear the image view for a panel created by create_afm_image_panel()."""
        if target_panel is None:
            return
        try:
            container = target_panel.findChild(QWidget, "afm_image_container")
            if container is None:
                return
            layout = container.layout()
            placeholder = container.findChild(QLabel, "afm_placeholder")
            view = container.findChild(_AspectPixmapView, "afm_image_view")
            if view is not None:
                view.setSourcePixmap(None)
            if layout is not None and hasattr(layout, "setCurrentWidget") and placeholder is not None:
                layout.setCurrentWidget(placeholder)
        except Exception:
            pass

